%macro analyse_alertes_complet(path_export=);

/* Étape 1 : Extraction de toutes les alertes unitaires */
data alertes_flag;
set flux_alertes;
array alertes b_: a_:;
length prefix type cd varname direction $30 nb_et 8.;
do i = 1 to dim(alertes);
    if alertes[i] = 1 then do;
        varname = vname(alertes[i]);
        /* Déterminer si c'est une baisse ou une augmentation */
        if substr(varname, 1, 1) = 'b' then direction = 'baisse';
        else if substr(varname, 1, 1) = 'a' then direction = 'augmentation';

        /* Extraire les composants du nom de variable */
        if direction = 'baisse' then do;
            prefix = scan(varname, 2, '_');
            type = scan(varname, 3, '_');
            cd = scan(varname, 4, '_');
            mois = input(compress(scan(varname, 5, '_'), 'M'), 8.);
            nb_et = input(compress(scan(varname, 6, '_'), 'ET'), 8.);
        end;
        else do; /* augmentation */
            prefix = scan(varname, 2, '_');
            type = scan(varname, 3, '_');
            cd = scan(varname, 4, '_');
            mois = input(compress(scan(varname, 5, '_'), 'M'), 8.);
            nb_et = input(compress(scan(varname, 6, '_'), 'ET'), 8.);
        end;

        alerte_flag = 1;
        output;
    end;
end;
