    by alerte_type;
    id mois;
    var nb_premieres_alertes;
run;

proc transpose data=distrib_mois_part out=distrib_pct_part_pivot(drop=_name_) prefix=pct_premAlerte_M;
    by alerte_type;
    id mois;
    var pct_premieres_alertes;
run;

/* Fusion des résultats pour id_part */
data resultats_part;
    merge analyse_complete_part 
          distrib_nb_part_pivot
          distrib_pct_part_pivot;
    by alerte_type;
    niveau = "id_part";
run;

/* Étape 5: Répéter l'analyse pour nu_cpte */
proc sql;
    /* Nombre total de comptes dans la base */
    create table total_comptes as
    select top_attrition, count(distinct nu_cpte) as total_comptes
    from flux_alertes
    group by top_attrition;

    /* Analyse des alertes par type */
    create table analyse_alertes_cpte as
    select 
        a.alerte_type,
        count(distinct a.nu_cpte) as nb_alertes_total,
        sum(case when b.top_attrition = 1 then 1 else 0 end) as nb_vrais_positifs,
        sum(case when b.top_attrition = 0 then 1 else 0 end) as nb_faux_positifs,
        calculated nb_vrais_positifs / calculated nb_alertes_total as taux_succes format=percent8.1
    from 
        (select distinct nu_cpte, alerte_type from alertes_stop) a
        inner join flux_alertes b on a.nu_cpte = b.nu_cpte
    group by 
        a.alerte_type;

    /* Joindre avec les totaux pour calculer les taux */
    create table analyse_complete_cpte as
    select 
        a.*,
        (select total_comptes from total_comptes where top_attrition = 1) as total_comptes_partis,
        (select total_comptes from total_comptes where top_attrition = 0) as total_comptes_non_partis,
        a.nb_vrais_positifs / (select total_comptes from total_comptes where top_attrition = 1) 
            as taux_vrais_positifs format=percent8.1,
        a.nb_faux_positifs / (select total_comptes from total_comptes where top_attrition = 0) 
            as taux_faux_positifs format=percent8.1
    from 
        analyse_alertes_cpte a;

    /* Distribution des premières alertes par mois */
    create table distrib_mois_cpte as
    select 
        a.alerte_type,
        a.premier_mois_alerte as mois,
        count(distinct a.nu_cpte) as nb_premieres_alertes,
        count(distinct a.nu_cpte) / 
            (select count(distinct nu_cpte) from premiere_alerte where alerte_type = a.alerte_type) 
            as pct_premieres_alertes format=percent8.1
    from 
        premiere_alerte a
    group by 
        a.alerte_type, a.premier_mois_alerte
    order by 
        a.alerte_type, a.premier_mois_alerte;
quit;

/* Pivotage pour avoir les mois en colonnes - nombre et pourcentage */
proc transpose data=distrib_mois_cpte out=distrib_nb_cpte_pivot(drop=_name_) prefix=nb_premAlerte_M;
    by alerte_type;
    id mois;
    var nb_premieres_alertes;
run;

proc transpose data=distrib_mois_cpte out=distrib_pct_cpte_pivot(drop=_name_) prefix=pct_premAlerte_M;
    by alerte_type;
    id mois;
    var pct_premieres_alertes;
run;

/* Fusion des résultats pour nu_cpte */
data resultats_cpte;
    merge analyse_complete_cpte 
          distrib_nb_cpte_pivot
          distrib_pct_cpte_pivot;
    by alerte_type;
    niveau = "nu_cpte";
run;

/* Étape 6: Combiner tous les résultats */
data resultats_finaux;
    set resultats_cli resultats_part resultats_cpte;
run;

