%macro analyse_alertes_complet(path_export=);

/* Étape 1 : Extraction de toutes les alertes unitaires */
data alertes_flag;
set flux_alertes;
array alertes b_: a_:;
length prefix type cd varname direction $30 nb_et 8.;
do i = 1 to dim(alertes);
    if alertes[i] = 1 then do;
        varname = vname(alertes[i]);
        /* Déterminer si c'est une baisse ou une augmentation */
        if substr(varname, 1, 1) = 'b' then direction = 'baisse';
        else if substr(varname, 1, 1) = 'a' then direction = 'augmentation';

        /* Extraire les composants du nom de variable */
        if direction = 'baisse' then do;
            prefix = scan(varname, 2, '_');
            type = scan(varname, 3, '_');
            cd = scan(varname, 4, '_');
            mois = input(compress(scan(varname, 5, '_'), 'M'), 8.);
            nb_et = input(compress(scan(varname, 6, '_'), 'ET'), 8.);
        end;
        else do; /* augmentation */
            prefix = scan(varname, 2, '_');
            type = scan(varname, 3, '_');
            cd = scan(varname, 4, '_');
            mois = input(compress(scan(varname, 5, '_'), 'M'), 8.);
            nb_et = input(compress(scan(varname, 6, '_'), 'ET'), 8.);
        end;

        alerte_flag = 1;
        output;
    end;
end;
keep nu_cpte id_part id_cli_cial prefix type cd mois nb_et direction alerte_flag top_attrition;
run;

/* Étape 2 : Bloc d'analyse générique par niveau */
%macro bloc(niveau=, sortie=);
proc sql;
create table base_&sortie as
select distinct &niveau, prefix, type, cd, mois, nb_et, direction, alerte_flag, top_attrition
from alertes_flag;
quit;

proc sql;
    /*Total par top_attrition*/
    create table total_attrition_&sortie as 
    select top_attrition, 
        count(distinct &niveau) as total
    from flux_alertes
    group by top_attrition;
quit;

/*Nb d'entités avec alerte par attrition, direction et seuil d'écart-type */
proc sql;
    create table nb_alertes_&sortie as 
    select prefix, type, cd, direction, nb_et, top_attrition, 
        count(distinct &niveau) as nb_avec_alerte
    from base_&sortie 
    group by prefix, type, cd, direction, nb_et, top_attrition;
quit;

/*Jointure et calcul des pourcentages */
proc sql;
    create table stats_&sortie as 
    select a.prefix, a.type, a.cd, a.direction, a.nb_et,
            b.total, 
            a.nb_avec_alerte, 
            (a.nb_avec_alerte / b.total) as taux_alerte format=percent6.1,
            a.top_attrition
    from nb_alertes_&sortie a 
    left join total_attrition_&sortie b
    on a.top_attrition = b.top_attrition;
quit;

data stats_&sortie;
    set stats_&sortie;
    if top_attrition = 1 then do;
        nb_vrais_pos = nb_avec_alerte;
        taux_vrais_pos = taux_alerte;
    end;
    else do;
        nb_faux_pos = nb_avec_alerte;
        taux_faux_pos = taux_alerte;
    end;
run;

/*Fusion des lignes top_attrition = 1 et 0 pour chaque flux*/
proc sort data=stats_&sortie; by prefix type cd direction nb_et; run;
proc means data=stats_&sortie noprint;
    by prefix type cd direction nb_et;
    var nb_vrais_pos nb_faux_pos taux_vrais_pos taux_faux_pos;
