run;

proc sql;
create table delai_&sortie as
select prefix, type, cd, direction, nb_et,
min(mois) as delai_min,
max(mois) as delai_max,
mean(mois) as delai_moyen format=8.2,
median(mois) as delai_median
from base_&sortie
where top_attrition = 1
group by prefix, type, cd, direction, nb_et;
quit;

/* Identification de la première alerte par client/compte pour chaque combinaison */
proc sql;
create table premiere_alerte_&sortie as
select &niveau, prefix, type, cd, direction, nb_et, min(mois) as premier_mois_alerte
from base_&sortie
group by &niveau, prefix, type, cd, direction, nb_et;
quit;

/* Distribution des premières alertes par mois */
proc sql;
/* D'abord, calculer le nombre total de clients/comptes avec alerte par combinaison */
create table total_clients_alerte_&sortie as
select prefix, type, cd, direction, nb_et, 
       count(distinct &niveau) as total_clients_alerte
from premiere_alerte_&sortie
group by prefix, type, cd, direction, nb_et;

/* Ensuite, calculer la distribution des premières alertes par mois */
create table distrib_premiere_alerte_&sortie as
select a.prefix, a.type, a.cd, a.direction, a.nb_et, a.premier_mois_alerte as mois, 
       count(distinct a.&niveau) as nb_premieres_alertes,
       (calculated nb_premieres_alertes / b.total_clients_alerte) as pct_premieres_alertes format=percent8.1
from premiere_alerte_&sortie a
join total_clients_alerte_&sortie b
  on a.prefix = b.prefix and a.type = b.type and a.cd = b.cd 
     and a.direction = b.direction and a.nb_et = b.nb_et
group by a.prefix, a.type, a.cd, a.direction, a.nb_et, a.premier_mois_alerte, b.total_clients_alerte
order by a.prefix, a.type, a.cd, a.direction, a.nb_et, a.premier_mois_alerte;
quit;

/* Pivotage pour avoir les mois en colonnes - nombre de premières alertes */
