               prefix=pct_premAlerte_M;
    by prefix type cd direction nb_et;
    id mois;
    var pct_premieres_alertes;
run;

/* Fusion des résultats */
data resultats_&sortie;
merge stats_&sortie delai_&sortie;
by prefix type cd direction nb_et;
niveau = "&niveau";
run;

/* Ajout de la distribution des premières alertes par mois */
