        if substr(varname, 1, 1) = 'b' then direction = 'baisse';
        else if substr(varname, 1, 1) = 'a' then direction = 'augmentation';

        /* Extraire les composants du nom de variable */
        if direction = 'baisse' then do;
            prefix = scan(varname, 2, '_');
