            mois = input(compress(scan(varname, 5, '_'), 'M'), 8.);
            nb_et = input(compress(scan(varname, 6, '_'), 'ET'), 8.);
        end;
        else do; /* augmentation */
            prefix = scan(varname, 2, '_');
