import com.example.pipwow.model.Level
import javax.inject.Inject
import javax.inject.Singleton
import kotlin.random.Random

@Singleton
class GameData @Inject constructor() {

    // Liste de villes pour les niveaux
    private val cities = listOf(
        "Paris" to "PARIS",
        "Londres" to "LONDON",
        "Tokyo" to "TOKYO",
        "Moscou" to "MOSCOW",
        "Rome" to "ROMEIT",
        "Berlin" to "BERLIN",
        "Madrid" to "MADRID",
        "Athènes" to "ATHENS",
        "Pékin" to "BEIJING",
        "Delhi" to "DELHIIN",
        "Le Caire" to "CAIRO",
        "Sydney" to "SYDNEY",
        "Rio" to "RIODEJ",
        "Mexico" to "MEXICO",
        "New York" to "NEWYORK",
        "Toronto" to "TORONTO",
        "Vienne" to "VIENNA",
        "Lisbonne" to "LISBON",
        "Bangkok" to "BANGKOK",
        "Séoul" to "SEOUL"
    )

    // Liste de couleurs de dégradé pour les niveaux
    private val gradientColors = listOf(
        listOf(0xFF4A90E2, 0xFF2E5BBA), // Bleu
        listOf(0xFF8B4513, 0xFF654321), // Marron
        listOf(0xFFE74C3C, 0xFFC0392B), // Rouge
        listOf(0xFF1E3A8A, 0xFF3B82F6), // Bleu nuit
        listOf(0xFF27AE60, 0xFF2ECC71), // Vert
        listOf(0xFF8E44AD, 0xFF9B59B6), // Violet
        listOf(0xFFD35400, 0xFFE67E22), // Orange
        listOf(0xFF16A085, 0xFF1ABC9C), // Turquoise
        listOf(0xFF2C3E50, 0xFF34495E), // Bleu gris
        listOf(0xFFF39C12, 0xFFF1C40F)  // Jaune
    )

    // Cache pour les niveaux générés
    private var cachedLevels: List<Level>? = null

    fun getLevels(): List<Level> {
        // Retourner les niveaux du cache s'ils existent
        cachedLevels?.let { return it }

        // Sinon, générer de nouveaux niveaux
        val levels = mutableListOf<Level>()
        val shuffledCities = cities.shuffled(Random(System.currentTimeMillis()))

        // Créer 20 niveaux
        for (i in 1..20) {
            val cityIndex = (i - 1) % shuffledCities.size
            val (cityName, letters) = shuffledCities[cityIndex]

            // Calcul dynamique du nombre de mots
            val wordCount = when {
                letters.length <= 5 -> 5 + (i / 3)
                letters.length <= 7 -> 7 + (i / 2)
                else -> 10 + (i / 2)
            }.coerceAtMost(15) // Maximum 15 mots par niveau

            val words = generateWordsFromLetters(letters, wordCount)

            // Choisir des couleurs aléatoires pour le dégradé
            val colorIndex = Random.nextInt(gradientColors.size)

            levels.add(
                Level(
                    id = i,
                    locationName = cityName,
                    letters = letters,
                    words = words,
                    unlocked = i == 1,
                    backgroundColors = gradientColors[colorIndex]
                )
            )

            // Debug
            println("Niveau $i: $cityName - ${words.size} mots: ${words.take(5)}...")
        }

        // Sauvegarder dans le cache
        cachedLevels = levels
        return levels
    }

    // Génération améliorée des mots
    private fun generateWordsFromLetters(letters: String, count: Int): List<String> {
        val result = mutableListOf<String>()
        val letterSet = letters.toSet()

        // Dictionnaire de mots possibles
        val wordsByLetters = mapOf(
            "PARIS" to listOf("AIR", "AIS", "PAS", "PAR", "RAS", "SPA", "SAP", "RIA", "SIR", "PAIR", "PARI", "SARI"),
            "LONDRES" to listOf("DEL", "DEN", "DEO", "DER", "DES", "DON", "DOL", "DOS", "OSER", "ORNE", "ODES"),
            "TOKYO" to listOf("TOY", "KOY", "TOK", "YOK", "KOT", "TOKO", "KYOTO", "TOKOY"),
            "MOSCOW" to listOf("COO", "COW", "MOO", "OWS", "SCO", "COOM", "COOS", "MOWS", "SCOW"),
            "ROMEIT" to listOf("ROM", "TOM", "RIM", "TIE", "TOE", "RITE", "MITE", "TORE", "MORE"),
            "BERLIN" to listOf("BIN", "LIE", "LIN", "NIL", "BRIE", "RILE", "LINE", "NILE", "LIEN"),
            "MADRID" to listOf("MAD", "RID", "AIR", "DAM", "RAM", "RAID", "MAID", "ARID", "DRAM"),
            "ATHENS" to listOf("ANT", "HEN", "NET", "SET", "TEN", "NEAT", "THEN", "SENT", "HENS"),
            "BEIJING" to listOf("BEG", "BIN", "GIN", "JIG", "BEING", "JIBE", "JING", "NIGH"),
            "DELHIIN" to listOf("DIE", "HID", "HEN", "HIDE", "LEND", "LINE", "LIED", "HIND", "HELD", "INDI"),
            "CAIRO" to listOf("AIR", "CAR", "OAR", "ROC", "ROA", "COIR", "ARCO", "CIAO", "COAT", "ORCA"),
            "SYDNEY" to listOf("DEN", "END", "DYE", "SEE", "DENY", "SEND", "NEED", "SEEN"),
            "RIODEJ" to listOf("DIE", "JOE", "RED", "ROD", "DIRE", "RODE", "JEDI", "JER"),
            "MEXICO" to listOf("COI", "CIE", "MIX", "MEC", "MIXE","MOI","OIE","EMOI", "CIME"),
            "NEWYORK" to listOf("NEW", "YOK", "ORK", "WOK", "YOKE", "WORK", "WORE", "WOKE"),
            "TORONTO" to listOf("TOO", "TON", "NOT", "ROT", "TOON", "ROOT", "TORO", "ONTO"),
            "VIENNA" to listOf("VAN", "INN", "ANN", "NAVE", "VAIN", "VINE", "VEIN", "NEVA"),
            "LISBON" to listOf("BIN", "LIB", "NOB", "SON", "BOIL", "SOIL", "LION", "LOIN"),
            "BANGKOK" to listOf("BAG", "BOK", "GOK", "KOB", "BANG", "BANK", "KONG", "KNOB"),
            "SEOUL" to listOf("SUE", "SOL", "OLE", "USE", "SOUL", "SOLE", "LOSE", "SLOE")
        )

        // 1. Utiliser d'abord les mots prédéfinis
        wordsByLetters[letters]?.let { predefined ->
            return if (predefined.size >= count) {
                predefined.shuffled().take(count)
            } else {
                predefined + generateRandomWords(letters, count - predefined.size)
            }
        }

        // 2. Génération aléatoire si pas dans le dictionnaire
        return generateRandomWords(letters, count)
    }

    private fun generateRandomWords(letters: String, count: Int): List<String> {
        val result = mutableListOf<String>()
        val letterList = letters.toList()
        val maxLength = letters.length // Plus de limite à 5

        while (result.size < count && result.size < 20) {
            val wordLength = Random.nextInt(3, maxLength + 1)
            val word = (1..wordLength)
                .map { letterList.random() }
                .joinToString("")
                .uppercase()

            if (!result.contains(word)) {
                result.add(word)
            }
        }

        return result
    }

    fun getLevelBackgroundColors(levelId: Int): List<Long> {
        return getLevels().firstOrNull { it.id == levelId }?.backgroundColors
            ?: listOf(0xFF8B4513, 0xFFD2B48C) // Dégradé par défaut
    }
}


