package com.example.pipwow.data

import com.example.pipwow.model.GameState
import com.example.pipwow.model.Level
import javax.inject.Inject
import javax.inject.Singleton
import androidx.compose.ui.graphics.Color

@Singleton
class GameRepository @Inject constructor(
    private val gameData: GameData,
    private val levelProgressManager: LevelProgressManager
) {
    // Cache pour optimiser les accès
    private val _allLevels by lazy { gameData.getLevels() }
    private var currentState = GameState()
    private var currentLevelData: Level? = null
    fun getLevel(levelId: Int): Level {
        return gameData.getLevels().firstOrNull { it.id == levelId }
            ?: throw IllegalArgumentException("Level $levelId not found")
    }
    fun getLevelBackgroundColors(levelId: Int): List<Color> {
        return gameData.getLevelBackgroundColors(levelId)
            .map { Color(it) }
    }

    fun loadLevel(levelId: Int): GameState {
        val level = _allLevels.firstOrNull { it.id == levelId }
            ?: throw IllegalArgumentException("Level $levelId not found")

        currentLevelData = level

        currentState = GameState(
            currentLevel = levelId,
            letters = level.letters,
            shuffledLetters = level.letters.toList().shuffled(),
            remainingWords = level.words.sortedBy { it.length },
            foundWords = emptyList(),
            backgroundColors = level.backgroundColors, // Cette ligne est cruciale
            selectedIndices = emptyList(),
            isLevelCompleted = false,
            score = 0,
            locationName = level.locationName
        )

        return currentState
    }

    fun isValidWord(word: String): Boolean {
        return currentLevelData?.words?.contains(word.uppercase()) ?: false
    }

    fun checkWord(selectedIndices: List<Int>, shuffledLetters: List<Char>): GameState {
        val word = selectedIndices
            .sorted()
            .map { shuffledLetters[it] }
            .joinToString("")
            .uppercase()

        if (!isValidWord(word)) {
            return currentState.copy(selectedIndices = emptyList())
        }

        val newFoundWords = currentState.foundWords + word
        val newRemainingWords = currentState.remainingWords - word
        val isCompleted = newRemainingWords.isEmpty()

        currentState = currentState.copy(
            foundWords = newFoundWords,
            remainingWords = newRemainingWords,
            isLevelCompleted = isCompleted,
            selectedIndices = emptyList(),
            score = currentState.score + calculateWordScore(word),
            lastFoundWord = word
        )

        if (isCompleted) {
            levelProgressManager.completeLevel(currentState.currentLevel)
        }

        return currentState
    }

    private fun calculateWordScore(word: String): Int {
        return when (word.length) {
            in 0..3 -> word.length * 10
            in 4..5 -> word.length * 15
            else -> word.length * 20
        }
    }

    fun getCurrentLevelData(): Level? = currentLevelData
}

