package com.example.pipwow

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.pipwow.data.GameRepository
import com.example.pipwow.data.LevelProgressManager
import com.example.pipwow.model.GameState
import com.example.pipwow.model.Level
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch
import javax.inject.Inject
import androidx.compose.ui.graphics.Color
import androidx.compose.runtime.mutableStateListOf

@HiltViewModel
class GameViewModel @Inject constructor(
    private val repository: GameRepository,
    private val levelProgressManager: LevelProgressManager
) : ViewModel() {
    // Déclaration correcte de _selectedIndices
    private val _selectedIndices = mutableStateListOf<Int>()
    val selectedIndices: List<Int> get() = _selectedIndices
    private val _gameState = MutableStateFlow(GameState())
    val gameState: StateFlow<GameState> = _gameState.asStateFlow()

    // Nouveau: Récupère les couleurs d'arrière-plan
    val currentBackgroundColors: List<Color>
        get() = repository.getLevelBackgroundColors(_gameState.value.currentLevel)
    fun getLevelTotalWords(levelId: Int): Int {
        return repository.getLevel(levelId).words.size
    }
    // Chargement du niveau avec gestion des stats
    fun loadLevel(levelId: Int) {
        viewModelScope.launch {
            repository.loadLevel(levelId).let { newState ->
                _gameState.update {
                    it.copy(
                        currentLevel = newState.currentLevel,
                        letters = newState.letters,
                        shuffledLetters = newState.shuffledLetters,
                        remainingWords = newState.remainingWords, // Tous les mots sont chargés ici
                        foundWords = newState.foundWords,
                        locationName = newState.locationName,
                        score = newState.score,
                        backgroundColors = newState.backgroundColors,// Cette ligne est cruciale
                        levelStartTime = System.currentTimeMillis() // Réinitialiser le timer
                    )
                }
                // Debug pour vérifier le nombre de mots
                println("Niveau ${newState.currentLevel} chargé avec ${newState.remainingWords.size} mots à trouver")
                println("Mots à trouver: ${newState.remainingWords}")
            }
        }
    }
    fun getCurrentWord(): String {
        return _gameState.value.selectedIndices
            .sorted()
            .map { _gameState.value.shuffledLetters[it] }
            .joinToString("")
    }
    fun addSelectedIndex(index: Int) {
        _gameState.update { state ->
            if (index in state.shuffledLetters.indices && !state.selectedIndices.contains(index)) {
                state.copy(
                    selectedIndices = state.selectedIndices + index,
                    //selectedLetters = state.selectedLetters + state.shuffledLetters[index]
                )
            } else {
                state
            }
        }
    }


    fun clearSelectedLetters() {
        _gameState.update { state ->
            state.copy(
                selectedIndices = emptyList(),
                //selectedLetters = emptyList()
            )
        }
    }
    private fun calculateWordScore(word: String): Int {
        return when {
            word.length <= 3 -> word.length * 10
            word.length <= 5 -> word.length * 15
            else -> word.length * 20
        }
    }
    fun checkWord() {
        _gameState.update { state ->
            val word = state.selectedIndices
                .map { state.shuffledLetters[it] } // Ne pas trier
                .joinToString("")
                .uppercase()

            if (state.remainingWords.contains(word)) {
                val newFoundWords = state.foundWords + word
                val newRemainingWords = state.remainingWords - word

                // Debug important
                println("Mot validé: $word")
                println("Mots trouvés: $newFoundWords")
                println("Mots restants: $newRemainingWords")

                state.copy(
                    foundWords = newFoundWords,
                    remainingWords = newRemainingWords,
                    selectedIndices = emptyList(),
                    isLevelCompleted = newRemainingWords.isEmpty(),
                    score = state.score + calculateWordScore(word),
                    lastFoundWord = word
                ).also {
                    // Force le refresh de l'UI
                    _gameState.value = it
                }
            } else {
                state.copy(selectedIndices = emptyList())
            }
        }
    }
    fun resetForNewLevel() {
        _gameState.update { state ->
            state.copy(
                selectedIndices = emptyList(),  // Remplace selectedLetters
                isLevelCompleted = false,
                lastFoundWord = null  // Réinitialise aussi le dernier mot trouvé
            )
        }
    }
    fun loadNextLevel() {
        val currentLevelId = gameState.value.currentLevel
        val nextLevelId = currentLevelId + 1

        viewModelScope.launch {
            try {
                // Marquer le niveau actuel comme complété
                levelProgressManager.completeLevel(currentLevelId)

                // Charger le niveau suivant
                loadLevel(nextLevelId)

                println("Passage au niveau suivant: $nextLevelId")
            } catch (e: Exception) {
                println("Erreur lors du passage au niveau suivant: ${e.message}")
            }
        }
    }
    // Nouvelle version avec calcul des étoiles
    fun completeLevel() {
        val currentState = _gameState.value
        levelProgressManager.completeLevel(
            levelId = currentState.currentLevel,
            timeMs = System.currentTimeMillis() - currentState.levelStartTime,
            hintsUsed = currentState.hintUsedCount
        )
    }

    // Méthode pour utiliser un indice
    fun useHint() {
        _gameState.update { state ->
            state.copy(
                hintUsedCount = state.hintUsedCount + 1, // Nouveau champ
                score = (state.score - 50).coerceAtLeast(0) // Pénalité de score
            )
        }
    }
}

