@Composable
fun PyramidBackground(
    modifier: Modifier = Modifier
) {
    Canvas(modifier = modifier) {
        val centerX = size.width / 2
        val bottomY = size.height

        // Pyramide principale
        val pyramidPath = Path().apply {
            moveTo(centerX - 150.dp.toPx(), bottomY)
            lineTo(centerX + 150.dp.toPx(), bottomY)
            lineTo(centerX, bottomY - 200.dp.toPx())
            close()
        }

        drawPath(
            path = pyramidPath,
            brush = Brush.verticalGradient(
                colors = listOf(
                    Color(0xFF8B4513),
                    Color(0xFF654321)
                )
            )
        )

        // Ombre de la pyramide
        val shadowPath = Path().apply {
            moveTo(centerX, bottomY - 200.dp.toPx())
            lineTo(centerX + 150.dp.toPx(), bottomY)
            lineTo(centerX + 200.dp.toPx(), bottomY)
            lineTo(centerX + 50.dp.toPx(), bottomY - 200.dp.toPx())
            close()
        }

        drawPath(
            path = shadowPath,
            color = Color.Black.copy(alpha = 0.3f)
        )

        // Pyramide secondaire (plus petite, à gauche)
        if (size.width > 300.dp.toPx()) {
            val leftPyramidPath = Path().apply {
                moveTo(50.dp.toPx(), bottomY)
                lineTo(150.dp.toPx(), bottomY)
                lineTo(100.dp.toPx(), bottomY - 120.dp.toPx())
                close()
            }

            drawPath(
                path = leftPyramidPath,
                brush = Brush.verticalGradient(
                    colors = listOf(
                        Color(0xFF8B4513).copy(alpha = 0.7f),
                        Color(0xFF654321).copy(alpha = 0.7f)
                    )
                )
            )
        }
    }
}

