@Composable
private fun CircularLetterGameArea(
    letters: List<Char>,
    selectedIndices: List<Int>,
    currentWord: String,
    primaryColor: Color,
    onLetterSelected: (Int) -> Unit,
    onWordSubmitted: () -> Unit,
    onClearSelection: () -> Unit
) {
    val density = LocalDensity.current

    Box(
        modifier = Modifier.size(280.dp),
        contentAlignment = Alignment.Center
    ) {
        Box(
            modifier = Modifier
                .size(200.dp)
                .background(
                    Color.White.copy(alpha = 0.1f),
                    CircleShape
                )
                .clip(CircleShape)
        )

        letters.forEachIndexed { index, letter ->
            val angle = (2 * PI * index / letters.size).toFloat() - PI.toFloat() / 2
            val radius = 100.dp

            with(density) {
                val x = radius.toPx() * cos(angle)
                val y = radius.toPx() * sin(angle)

                Box(
                    modifier = Modifier.offset(
                        x = x.toDp(),
                        y = y.toDp()
                    )
                ) {
                    EnhancedLetterTile(
                        letter = letter,
                        index = index,
                        isSelected = selectedIndices.contains(index),
                        onClick = { onLetterSelected(index) }
                    )
                }
            }
        }

        Column(
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            Button(
                onClick = onWordSubmitted,
                colors = ButtonDefaults.buttonColors(
                    containerColor = MaterialTheme.colorScheme.primary.copy(alpha = 0.8f)
                ),
                shape = CircleShape,
                modifier = Modifier.size(48.dp),
                contentPadding = PaddingValues(0.dp)
            ) {
                Text(
                    text = "✓",
                    color = Color.White,
                    fontSize = 20.sp,
                    fontWeight = FontWeight.Bold
                )
            }

            OutlinedButton(
                onClick = onClearSelection,
                colors = ButtonDefaults.outlinedButtonColors(
                    contentColor = Color.White
                ),
                border = BorderStroke(2.dp, Color.White.copy(alpha = 0.7f)),
                shape = CircleShape,
                modifier = Modifier.size(48.dp),
                contentPadding = PaddingValues(0.dp)
            ) {
                Text(
                    text = "✕",
                    color = Color.White,
                    fontSize = 20.sp,
                    fontWeight = FontWeight.Bold
                )
            }
        }
    }
}

