@OptIn(ExperimentalTextApi::class)
@Composable
fun EnhancedWordCrossGrid(
    grid: CrosswordGrid,
    foundWords: List<String>,
    modifier: Modifier = Modifier,
    cellSize: Dp = 16.dp
) {
    val textMeasurer = rememberTextMeasurer()
    val density = LocalDensity.current

    Box(
        modifier = modifier,
        contentAlignment = Alignment.Center
    ) {
        Canvas(modifier = Modifier.fillMaxSize()) {
            // Calcul dynamique de la taille des cases
            val gridSize = grid.size
            val availableWidth = size.width
            val availableHeight = size.height

            // Déterminer la taille maximale possible pour chaque case
            val cellSizeX = (availableWidth / gridSize)
            val cellSizeY = (availableHeight / gridSize)

            // Prendre la plus petite des deux dimensions pour avoir des cases carrées
            var cellSizePx = minOf(cellSizeX, cellSizeY)

            // Limiter la taille maximale des cases
            val maxCellSizePx = with(density) { 40.dp.toPx() }
            cellSizePx = minOf(cellSizePx, maxCellSizePx)

            // Calculer l'espacement proportionnel à la taille des cases
            val spacing = cellSizePx * 0.05f

            // Calculer le décalage pour centrer la grille
            val gridWidth = gridSize * cellSizePx + (gridSize - 1) * spacing
            val gridHeight = gridSize * cellSizePx + (gridSize - 1) * spacing
            val offsetX = (availableWidth - gridWidth) / 2
            val offsetY = (availableHeight - gridHeight) / 2

            // Calculer les tailles de police proportionnelles
            val fontSize = cellSizePx * 0.7f
            val numberFontSize = cellSizePx * 0.35f
            val cornerRadiusPx = cellSizePx * 0.15f
            val borderWidth = cellSizePx * 0.1f

            // Dessiner d'abord tous les emplacements potentiels
            grid.wordPlacements.forEach { placement ->
                placement.positions.forEach { pos ->
                    val x = pos.x
                    val y = pos.y

                    // Calculer la position réelle en tenant compte de l'espacement
                    val xPos = offsetX + x * (cellSizePx + spacing)
                    val yPos = offsetY + y * (cellSizePx + spacing)

                    // Vérifier que la cellule est dans les limites du canvas
                    if (xPos + cellSizePx <= size.width && yPos + cellSizePx <= size.height) {
                        // Fond blanc semi-transparent
                        drawRoundRect(
                            color = Color.White.copy(alpha = 0.2f),
                            topLeft = Offset(xPos, yPos),
                            size = Size(cellSizePx, cellSizePx),
                            cornerRadius = CornerRadius(cornerRadiusPx)
                        )
                        // Bordure noire
                        drawRoundRect(
                            color = Color.Black.copy(alpha = 0.6f),
                            topLeft = Offset(xPos, yPos),
                            size = Size(cellSizePx, cellSizePx),
                            cornerRadius = CornerRadius(cornerRadiusPx),
                            style = Stroke(width = borderWidth)
                        )
                    }
                }
            }

            // Ensuite, dessiner les mots trouvés par-dessus
            grid.cells.forEachIndexed { y, row ->
                row.forEachIndexed { x, cell ->
                    if (cell.char != null) {
                        // Calculer la position réelle en tenant compte de l'espacement
                        val xPos = offsetX + x * (cellSizePx + spacing)
                        val yPos = offsetY + y * (cellSizePx + spacing)

                        // Vérifier que la cellule est dans les limites du canvas
                        if (xPos + cellSizePx <= size.width && yPos + cellSizePx <= size.height) {
                            val isPartOfFoundWord = grid.wordPlacements.any { placement ->
                                placement.positions.any { it.x == x && it.y == y } &&
                                        foundWords.contains(placement.word)
                            }

                            if (isPartOfFoundWord) {
                                // Dessiner la cellule pour les mots trouvés
                                drawRoundRect(
                                    color = Color(0xFF4CAF50),
                                    topLeft = Offset(xPos, yPos),
                                    size = Size(cellSizePx, cellSizePx),
                                    cornerRadius = CornerRadius(cornerRadiusPx)
                                )

                                // Dessiner la lettre
                                val letterText = textMeasurer.measure(
                                    text = cell.char.toString(),
                                    style = TextStyle(
                                        color = Color.White,
                                        fontSize = with(density) { fontSize.toSp() },
                                        fontWeight = FontWeight.Bold,
                                        textAlign = TextAlign.Center
                                    )
                                )

                                drawText(
                                    textLayoutResult = letterText,
                                    topLeft = Offset(
                                        xPos + (cellSizePx - letterText.size.width) / 2,
                                        yPos + (cellSizePx - letterText.size.height) / 2
                                    )
                                )
                            }

                            // Dessiner le numéro du mot (s'il existe)
                            if (cell.wordNumber != null) {
                                val numberText = textMeasurer.measure(
                                    text = cell.wordNumber.toString(),
                                    style = TextStyle(
                                        color = if (isPartOfFoundWord) Color.White else Color.Black.copy(alpha = 0.8f),
                                        fontSize = with(density) { numberFontSize.toSp() },
                                        fontWeight = FontWeight.Bold
                                    )
                                )

                                drawText(
                                    textLayoutResult = numberText,
                                    topLeft = Offset(
                                        xPos + cellSizePx * 0.1f,
                                        yPos + cellSizePx * 0.2f
                                    )
                                )
                            }
                        }
                    }
                }
            }
        }
    }
}

