        // Utilisation correcte des propriétés du scope
        val containerSize = min(scope.maxWidth, scope.maxHeight) * maxSizePercent
        val squareSize = containerSize / (crossSize * 1.1f)

        Canvas(modifier = Modifier.size(containerSize)) {
            val centerX = size.width / 2
            val centerY = size.height / 2
            val spacing = 2.dp.toPx()
            val squareSizePx = squareSize.toPx()
            val textSizePx = squareSizePx * 0.35f

            for (i in 0 until crossSize) {
                for (j in 0 until crossSize) {
                    val shouldDraw = (i == crossSize / 2) || (j == crossSize / 2)
                    if (shouldDraw) {
                        val x = centerX - (crossSize * (squareSizePx + spacing)) / 2 + j * (squareSizePx + spacing)
                        val y = centerY - (crossSize * (squareSizePx + spacing)) / 2 + i * (squareSizePx + spacing)

                        val wordIndex = if (i == crossSize / 2) j else i + crossSize
                        val isWordFound = wordIndex < foundWords.size
                        val tileColor = if (isWordFound) Color(0xFF4CAF50) else Color.Gray.copy(alpha = 0.3f)

                        drawRoundRect(
                            color = tileColor,
                            topLeft = Offset(x, y),
                            size = Size(squareSizePx, squareSizePx),
                            cornerRadius = CornerRadius(4.dp.toPx())
                        )

                        if (isWordFound) {
                            drawContext.canvas.nativeCanvas.drawText(
                                foundWords[wordIndex].first().toString(),
                                x + squareSizePx / 2,
                                y + squareSizePx / 2 + (textSizePx / 3),
                                Paint().apply {
                                    color = android.graphics.Color.WHITE
                                    textSize = textSizePx
                                    textAlign = Paint.Align.CENTER
                                    isFakeBoldText = true
                                }
                            )
                        }
                    }
                }
            }
        }
    }
}
```

### Clés de la solution :

1. **Accès explicite au scope** :
   ```kotlin
   BoxWithConstraints { scope ->  // Nommage explicite du paramètre scope
       scope.maxWidth // Accès via le scope nommé
       scope.maxHeight
   }
   ```

2. **Corrections supplémentaires** :
   - Suppression de `LocalDensity.current` inutile
   - Calculs de taille directement en Dp
   - Conversion en pixels uniquement pour le Canvas

3. **Version alternative (sans nommer le scope)** :
   ```kotlin
   BoxWithConstraints( // Le scope est this implicite
       modifier = modifier,
       contentAlignment = Alignment.Center
   ) {
       val containerSize = min(maxWidth, maxHeight) * maxSizePercent // Accès direct
       // ... reste inchangé ...
   }
   ```

### Pourquoi ça marche maintenant :
- L'accès à `maxWidth`/`maxHeight` se fait explicitement via le scope de `BoxWithConstraints`
- Les conversions d'unités sont gérées proprement
- La structure respecte les bonnes pratiques de Compose

