// Nouvelle classe pour représenter une position dans la grille
data class GridPosition(val x: Int, val y: Int)

data class WordPlacement(
    val word: String,
    val positions: List<GridPosition>,
    val orientation: Orientation
)

enum class Orientation { HORIZONTAL, VERTICAL }

data class CrosswordCell(
    val char: Char? = null,
    val isHorizontalStart: Boolean = false,
    val isVerticalStart: Boolean = false,
    var wordNumber: Int? = null,
    val isFound: Boolean = false
)

data class CrosswordWord(
    val text: String,
    val startX: Int,
    val startY: Int,
    val isHorizontal: Boolean,
    var number: Int?,
    val isFound: Boolean
)

data class CrosswordGrid(
    val size: Int,
    val cells: List<List<CrosswordCell>>,
    val words: List<CrosswordWord>,
    val wordPlacements: List<WordPlacement> = emptyList()
)

// Générateur de grille

class CrosswordGenerator(private val gridSize: Int = 17) {
    private lateinit var grid: Array<Array<CrosswordCell?>>
    private val placedWords = mutableListOf<CrosswordWord>()
    private val wordPlacements = mutableListOf<WordPlacement>()

    fun generate(words: List<String>): CrosswordGrid {
        val validWords = words.distinct().filter { it.length <= gridSize }
        if (validWords.isEmpty()) return createEmptyGrid()

        // Essayer plusieurs configurations
        for (attempt in 1..3) {
            resetGrid()
            placedWords.clear()
            wordPlacements.clear()

            // Trier par longueur décroissante
            val sortedWords = validWords.sortedByDescending { it.length }
            placeFirstWord(sortedWords.first())

            var allPlaced = true
            for (word in sortedWords.drop(1)) {
                if (!tryPlaceWord(word, 100)) {
                    allPlaced = false
                    break
                }
            }

            if (allPlaced) {
                assignWordNumbers()
                return buildGrid() // Renommage de la méthode
            }
        }

        // Fallback qui place tous les mots verticalement
        return createFullFallbackGrid(validWords)
    }
    private fun createFullFallbackGrid(words: List<String>): CrosswordGrid {
        resetGrid()
        placedWords.clear()
        wordPlacements.clear()

        var currentY = 1
        val sortedWords = words.sortedByDescending { it.length }

        sortedWords.forEach { word ->
            if (currentY < gridSize - word.length) {
                placeWord(
                    word = word,
                    startX = 1, // Colonne fixe
                    startY = currentY,
                    isHorizontal = false
                )
                currentY += word.length + 2 // Espacement
            }
        }

        assignWordNumbers()
        return buildGrid()
    }
    private fun buildGrid(): CrosswordGrid {
        val cells = List(gridSize) { y ->
            List(gridSize) { x ->
                grid[y][x] ?: CrosswordCell()
            }
        }
        return CrosswordGrid(
            size = gridSize,
            cells = cells,
            words = placedWords,
            wordPlacements = wordPlacements
        )
    }

    private fun resetGrid() {
        grid = Array(gridSize) { arrayOfNulls(gridSize) }
    }

    private fun placeFirstWord(word: String) {
        // Essayer de placer le premier mot au centre, horizontalement ou verticalement
        val isHorizontal = Random.nextBoolean() // Aléatoire pour plus de variété

        if (isHorizontal) {
            val startX = max(0, (gridSize - word.length) / 2)
            val startY = gridSize / 2

            for (i in word.indices) {
                grid[startY][startX + i] = CrosswordCell(
                    char = word[i],
                    isHorizontalStart = i == 0,
                    isVerticalStart = false,
                    wordNumber = null,
                    isFound = true
                )
            }

            val crosswordWord = CrosswordWord(
                text = word,
                startX = startX,
                startY = startY,
                isHorizontal = true,
                number = null,
                isFound = true
            )
            placedWords.add(crosswordWord)

            wordPlacements.add(
                WordPlacement(
                    word = word,
                    positions = word.indices.map { GridPosition(startX + it, startY) },
                    orientation = Orientation.HORIZONTAL
                )
            )
        } else {
            val startX = gridSize / 2
            val startY = max(0, (gridSize - word.length) / 2)

            for (i in word.indices) {
                grid[startY + i][startX] = CrosswordCell(
                    char = word[i],
                    isHorizontalStart = false,
                    isVerticalStart = i == 0,
                    wordNumber = null,
                    isFound = true
                )
            }

            val crosswordWord = CrosswordWord(
                text = word,
                startX = startX,
                startY = startY,
                isHorizontal = false,
                number = null,
                isFound = true
            )
            placedWords.add(crosswordWord)

            wordPlacements.add(
                WordPlacement(
                    word = word,
                    positions = word.indices.map { GridPosition(startX, startY + it) },
                    orientation = Orientation.VERTICAL
                )
            )
        }
    }

    private fun tryPlaceWord(word: String, maxAttempts: Int): Boolean {
        // Liste pour stocker toutes les positions possibles
        val possiblePlacements = mutableListOf<Triple<Int, Int, Boolean>>() // x, y, isHorizontal

        // Essayer de trouver des intersections avec les mots déjà placés
        for (placedWord in placedWords) {
            for (i in word.indices) {
                val letterToMatch = word[i]

                // Chercher cette lettre dans les mots déjà placés
                for (j in placedWord.text.indices) {
                    if (placedWord.text[j] == letterToMatch) {
                        // Calculer les positions possibles
                        if (placedWord.isHorizontal) {
                            // Essayer de placer verticalement
                            val x = placedWord.startX + j
                            val y = placedWord.startY - i

                            if (canPlaceWord(word, x, y, false)) {
                                possiblePlacements.add(Triple(x, y, false))
                            }
                        } else {
                            // Essayer de placer horizontalement
                            val x = placedWord.startX - i
                            val y = placedWord.startY + j

                            if (canPlaceWord(word, x, y, true)) {
                                possiblePlacements.add(Triple(x, y, true))
                            }
                        }
                    }
                }
            }
        }

        // Si aucun placement n'est possible avec des intersections, essayer sans intersection
        if (possiblePlacements.isEmpty()) {
            // Essayer de placer le mot sans intersection (en dernier recours)
            for (y in 0 until gridSize) {
                for (x in 0 until gridSize) {
                    if (canPlaceWord(word, x, y, true)) {
                        possiblePlacements.add(Triple(x, y, true))
                    }
                    if (canPlaceWord(word, x, y, false)) {
                        possiblePlacements.add(Triple(x, y, false))
                    }
                }
            }
        }

        // Choisir aléatoirement parmi les placements possibles
        if (possiblePlacements.isNotEmpty()) {
            val randomIndex = Random.nextInt(min(maxAttempts, possiblePlacements.size))
            val (x, y, isHorizontal) = possiblePlacements[randomIndex]
            placeWord(word, x, y, isHorizontal)
            return true
        }

        return false
    }

    private fun canPlaceWord(word: String, startX: Int, startY: Int, isHorizontal: Boolean): Boolean {
        // Vérifier si le mot sort de la grille
        if (isHorizontal) {
            if (startX < 0 || startX + word.length > gridSize) {
                return false
            }
        } else {
            if (startY < 0 || startY + word.length > gridSize) {
                return false
            }
        }

        var hasIntersection = false

        // Vérifier chaque position
        for (i in word.indices) {
            val x = if (isHorizontal) startX + i else startX
            val y = if (isHorizontal) startY else startY + i

            // Vérifier la case actuelle
            val cell = grid[y][x]
            if (cell != null) {
                // Si la case est déjà occupée, la lettre doit correspondre
                if (cell.char != word[i]) {
                    return false
                }
                hasIntersection = true
            } else {
                // Vérifier qu'il n'y a pas de lettres adjacentes (sauf aux intersections)
                if (isHorizontal) {
                    // Vérifier au-dessus et en-dessous
                    if ((y > 0 && grid[y-1][x] != null && i > 0 && i < word.length - 1) ||
                        (y < gridSize-1 && grid[y+1][x] != null && i > 0 && i < word.length - 1)) {
                        return false
                    }
                } else {
                    // Vérifier à gauche et à droite
                    if ((x > 0 && grid[y][x-1] != null && i > 0 && i < word.length - 1) ||
                        (x < gridSize-1 && grid[y][x+1] != null && i > 0 && i < word.length - 1)) {
                        return false
                    }
                }
            }
        }

        // Vérifier qu'il n'y a pas de mots adjacents
        if (isHorizontal) {
            // Vérifier avant et après
            if ((startX > 0 && grid[startY][startX-1] != null) ||
                (startX + word.length < gridSize && grid[startY][startX+word.length] != null)) {
                return false
            }
        } else {
            // Vérifier au-dessus et en-dessous
            if ((startY > 0 && grid[startY-1][startX] != null) ||
                (startY + word.length < gridSize && grid[startY+word.length][startX] != null)) {
                return false
            }
        }

        // Pour le premier mot, pas besoin d'intersection
        return placedWords.isEmpty() || hasIntersection
    }

    private fun placeWord(word: String, startX: Int, startY: Int, isHorizontal: Boolean) {
        val positions = mutableListOf<GridPosition>()

        for (i in word.indices) {
            val x = if (isHorizontal) startX + i else startX
            val y = if (isHorizontal) startY else startY + i
            positions.add(GridPosition(x, y))

            // Ne pas écraser les cellules existantes
            if (grid[y][x] == null) {
                grid[y][x] = CrosswordCell(
                    char = word[i],
                    isHorizontalStart = isHorizontal && i == 0,
                    isVerticalStart = !isHorizontal && i == 0,
                    wordNumber = null,
                    isFound = true
                )
            }
        }

        val crosswordWord = CrosswordWord(
            text = word,
            startX = startX,
            startY = startY,
            isHorizontal = isHorizontal,
            number = null,
            isFound = true
        )
        placedWords.add(crosswordWord)

        wordPlacements.add(
            WordPlacement(
                word = word,
                positions = positions,
                orientation = if (isHorizontal) Orientation.HORIZONTAL else Orientation.VERTICAL
            )
        )
    }

    private fun assignWordNumbers() {
        // Trier les mots par position (d'abord par ligne, puis par colonne)
        val sortedWords = placedWords.sortedWith(
            compareBy({ it.startY }, { it.startX })
        )

        var currentNumber = 1

        for (word in sortedWords) {
            if (word.number == null) {
                word.number = currentNumber++

                // Mettre à jour la cellule de départ
                val startX = word.startX
                val startY = word.startY
                val cell = grid[startY][startX]

                grid[startY][startX] = cell?.copy(
                    wordNumber = word.number,
                    isHorizontalStart = word.isHorizontal,
                    isVerticalStart = !word.isHorizontal
                )
            }
        }
    }

    private fun createEmptyGrid(): CrosswordGrid {
        return CrosswordGrid(
            size = gridSize,
            cells = List(gridSize) { List(gridSize) { CrosswordCell() } },
            words = emptyList(),
            wordPlacements = emptyList()
        )
    }

    private fun createFallbackGrid(words: List<String>): CrosswordGrid {
        // Solution de secours: placer tous les mots en ligne horizontale
        resetGrid()
        placedWords.clear()
        wordPlacements.clear()

        val sortedWords = words.sortedByDescending { it.length }
        var currentY = gridSize / 2 - sortedWords.size / 2

        for (word in sortedWords) {
            if (currentY >= gridSize) break

            val startX = max(0, (gridSize - word.length) / 2)

            for (i in word.indices) {
                if (startX + i < gridSize) {
                    grid[currentY][startX + i] = CrosswordCell(
                        char = word[i],
                        isHorizontalStart = i == 0,
                        isVerticalStart = false,
                        wordNumber = null,
                        isFound = true
                    )
                }
            }

            val crosswordWord = CrosswordWord(
                text = word,
                startX = startX,
                startY = currentY,
                isHorizontal = true,
                number = null,
                isFound = true
            )
            placedWords.add(crosswordWord)

            wordPlacements.add(
                WordPlacement(
                    word = word,
                    positions = word.indices.map { GridPosition(startX + it, currentY) },
                    orientation = Orientation.HORIZONTAL
                )
            )

            currentY++
        }

        assignWordNumbers()

        return CrosswordGrid(
            size = gridSize,
            cells = grid.map { row -> row.map { it ?: CrosswordCell() } },
            words = placedWords,
            wordPlacements = wordPlacements
        )
    }
}

