            "BEIJING" to listOf("BEG", "BIN", "GIN", "JIG", "BEING", "JIBE", "JING", "NIGH"),
            "DELHIIN" to listOf("DIE", "HID", "HEN", "HIDE", "LEND", "LINE", "LIED", "HIND", "HELD", "INDI"),
            "CAIRO" to listOf("AIR", "CAR", "OAR", "ROC", "ROA", "COIR", "ARCO", "CIAO", "COAT", "ORCA"),
            "SYDNEY" to listOf("DEN", "END", "DYE", "SEE", "DENY", "SEND", "NEED", "SEEN"),
            "RIODEJ" to listOf("DIE", "JOE", "RED", "ROD", "DIRE", "RODE", "JEDI", "JER"),
            "MEXICO" to listOf("COI", "CIE", "MIX", "MEC", "MIXE","MOI","OIE","EMOI", "CIME"),
            "NEWYORK" to listOf("NEW", "YOK", "ORK", "WOK", "YOKE", "WORK", "WORE", "WOKE"),
            "TORONTO" to listOf("TOO", "TON", "NOT", "ROT", "TOON", "ROOT", "TORO", "ONTO"),
            "VIENNA" to listOf("VAN", "INN", "ANN", "NAVE", "VAIN", "VINE", "VEIN", "NEVA"),
            "LISBON" to listOf("BIN", "LIB", "NOB", "SON", "BOIL", "SOIL", "LION", "LOIN"),
            "BANGKOK" to listOf("BAG", "BOK", "GOK", "KOB", "BANG", "BANK", "KONG", "KNOB"),
            "SEOUL" to listOf("SUE", "SOL", "OLE", "USE", "SOUL", "SOLE", "LOSE", "SLOE")
        )

        // 1. Utiliser d'abord les mots prédéfinis
        wordsByLetters[letters]?.let { predefined ->
            return if (predefined.size >= count) {
                predefined.shuffled().take(count)
            } else {
                predefined + generateRandomWords(letters, count - predefined.size)
            }
        }

        // 2. Génération aléatoire si pas dans le dictionnaire
        return generateRandomWords(letters, count)
    }

    private fun generateRandomWords(letters: String, count: Int): List<String> {
        val result = mutableListOf<String>()
        val letterList = letters.toList()
        val maxLength = letters.length // Plus de limite à 5

        while (result.size < count && result.size < 20) {
            val wordLength = Random.nextInt(3, maxLength + 1)
            val word = (1..wordLength)
                .map { letterList.random() }
                .joinToString("")
                .uppercase()

            if (!result.contains(word)) {
                result.add(word)
            }
        }

        return result
    }

    fun getLevelBackgroundColors(levelId: Int): List<Long> {
        return getLevels().firstOrNull { it.id == levelId }?.backgroundColors
            ?: listOf(0xFF8B4513, 0xFFD2B48C) // Dégradé par défaut
    }
}


