package com.example.pipwow.data

import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class LevelProgressManager @Inject constructor() {
    private val _unlockedLevels = MutableStateFlow<Set<Int>>(setOf(1)) // Niveau 1 débloqué par défaut
    private val _completedLevels = MutableStateFlow<Set<Int>>(emptySet())
    private val _levelStats = MutableStateFlow<Map<Int, LevelStats>>(emptyMap()) // Nouveau: Statistiques par niveau

    val unlockedLevels: StateFlow<Set<Int>> = _unlockedLevels.asStateFlow()
    val completedLevels: StateFlow<Set<Int>> = _completedLevels.asStateFlow()
    val levelStats: StateFlow<Map<Int, LevelStats>> = _levelStats.asStateFlow() // Nouveau

    data class LevelStats(
        val completionTime: Long = 0, // Temps en millisecondes
        val hintsUsed: Int = 0,
        val starsEarned: Int = 0 // 0-3 étoiles
    )

    // Marque un niveau comme complété et débloque le suivant
    fun completeLevel(levelId: Int, timeMs: Long = 0, hintsUsed: Int = 0) {
        _completedLevels.value = _completedLevels.value + levelId
        unlockLevel(levelId + 1)

        _levelStats.value = _levelStats.value.toMutableMap().apply {
            put(levelId, LevelStats(
                completionTime = timeMs,
                hintsUsed = hintsUsed,
                starsEarned = calculateStars(timeMs, hintsUsed)
            )) // Ferme LevelStats et put
        } // Ferme le bloc apply
    }


    private fun calculateStars(timeMs: Long, hintsUsed: Int): Int {
        return when {
            hintsUsed == 0 && timeMs < 60_000 -> 3 // 3 étoiles si rapide et sans indices
            hintsUsed <= 2 -> 2
            else -> 1
        }
    }
    fun isLevelUnlocked(levelId: Int): Boolean {
        return _unlockedLevels.value.contains(levelId)
    }

    fun isLevelCompleted(levelId: Int): Boolean {
        return _completedLevels.value.contains(levelId)
    }
    fun unlockLevel(levelId: Int) {
        if (!_unlockedLevels.value.contains(levelId)) {
            _unlockedLevels.value = _unlockedLevels.value + levelId
        }
    }

    // Nouveau: Récupère les stats d'un niveau spécifique
    fun getLevelStats(levelId: Int): LevelStats {
        return _levelStats.value[levelId] ?: LevelStats()
    }

    // Nouveau: Réinitialise la progression (pour debug/testing)
    fun resetProgress() {
        _unlockedLevels.value = setOf(1)
        _completedLevels.value = emptySet()
        _levelStats.value = emptyMap()
    }
}

