import kotlinx.coroutines.launch
import javax.inject.Inject
import dagger.hilt.android.lifecycle.HiltViewModel
import com.example.pipwow.data.LevelProgressManager

@HiltViewModel
class LevelSelectionViewModel @Inject constructor(
    private val levelProgressManager: LevelProgressManager,
    private val gameData: GameData
) : ViewModel() {

    private val _levels = MutableStateFlow<List<Level>>(emptyList())
    val levels: StateFlow<List<Level>> = _levels.asStateFlow()

    private val _isLoading = MutableStateFlow(false)
    val isLoading: StateFlow<Boolean> = _isLoading.asStateFlow()

    init {
        loadLevels()
    }

    fun loadLevels() {
        _isLoading.value = true
        viewModelScope.launch {
            // Combine les données statiques avec la progression
            val allLevels = gameData.getLevels().map { level ->
                level.copy(
                    unlocked = levelProgressManager.isLevelUnlocked(level.id),
                    completed = levelProgressManager.isLevelCompleted(level.id),
                    starsEarned = levelProgressManager.getLevelStats(level.id).starsEarned // Nouveau
                )
            }
            _levels.value = allLevels
            _isLoading.value = false
        }
    }

    fun unlockLevel(levelId: Int) {
        levelProgressManager.unlockLevel(levelId)
        updateLevelStatus(levelId)
    }

    // Nouvelle méthode pour rafraîchir un niveau spécifique
    private fun updateLevelStatus(levelId: Int) {
        _levels.value = _levels.value.map { level ->
            if (level.id == levelId) {
                level.copy(
                    unlocked = levelProgressManager.isLevelUnlocked(levelId),
                    completed = levelProgressManager.isLevelCompleted(levelId),
                    starsEarned = levelProgressManager.getLevelStats(levelId).starsEarned
                )
            } else level
        }
    }

    // Nouveau: Réinitialisation pour le debug
    fun resetProgress() {
        levelProgressManager.resetProgress()
        loadLevels() // Recharge tous les niveaux
    }
}

