@Composable
fun AdaptiveCrosswordGrid(
    crosswordGrid: CrosswordGrid,
    modifier: Modifier = Modifier
) {
    BoxWithConstraints(
        modifier = modifier
            .fillMaxWidth()
            .padding(16.dp)
