        val availableWidth = maxWidth - 32.dp // Soustraire le padding
        val cellSize = (availableWidth / crosswordGrid.size).coerceAtMost(48.dp)

        // Utiliser la taille calculée pour chaque cellule
        Column(
            horizontalAlignment = Alignment.CenterHorizontally
