```kotlin
@Composable
fun EnhancedLetterTile(
    letter: Char,
    index: Int,
    isSelected: Boolean = false,
    onClick: () -> Unit = {},
    modifier: Modifier = Modifier,
    tileSize: Dp = 48.dp
) {
    val density = LocalDensity.current
    val configuration = LocalConfiguration.current

    // Calcul de la taille adaptative en fonction de la largeur d'écran
    val adaptiveTileSize = remember(configuration) {
        val screenWidth = configuration.screenWidthDp
        when {
            screenWidth < 360 -> 40.dp  // Petits téléphones
            screenWidth < 600 -> tileSize  // Téléphones standards
            screenWidth < 840 -> 56.dp  // Grandes téléphones ou petites tablettes
            else -> 64.dp  // Tablettes
        }
    }

    val textPaint = remember {
        Paint().apply {
            color = Color.White.toArgb()
            textSize = with(density) { (adaptiveTileSize.value * 0.5).sp.toPx() }
            textAlign = Paint.Align.CENTER
            isFakeBoldText = true
        }
    }

    Canvas(
        modifier = modifier
            .size(adaptiveTileSize)
            .clickable(onClick = onClick)
    ) {
        val radius = this.size.minDimension / 2

        // Animation de sélection
        val selectedScale = if (isSelected) 1.1f else 1.0f

        withScale(
            scaleX = selectedScale,
            scaleY = selectedScale,
            pivot = Offset(this.size.width / 2, this.size.height / 2)
        ) {
            // Fond avec dégradé
            drawCircle(
                brush = Brush.radialGradient(
                    colors = if (isSelected) 
                        listOf(Color(0xFFFF8080), Color(0xFFFF6B6B)) 
                    else 
                        listOf(Color(0xFF3A70D1), Color(0xFF2E5BBA)),
                    center = Offset(this.size.width / 2, this.size.height / 2),
                    radius = radius * 1.2f
                ),
                radius = radius
            )

            // Effet de brillance
            drawCircle(
                color = Color.White.copy(alpha = 0.3f),
                radius = radius * 0.7f,
                center = Offset(
                    this.size.width / 2 - radius * 0.3f,
                    this.size.height / 2 - radius * 0.3f
                )
            )
        }

        // Texte de la lettre
        drawContext.canvas.nativeCanvas.drawText(
            letter.toString(),
            this.size.width / 2,
            this.size.height / 2 + (textPaint.textSize / 3),
            textPaint
        )
    }
}
```

Ce code modifié inclut les améliorations suivantes :

1. **Taille adaptative** : La taille de la tuile s'ajuste automatiquement en fonction de la largeur d'écran de l'appareil.
2. **Taille de texte proportionnelle** : La taille du texte est calculée proportionnellement à la taille de la tuile.
3. **Effets visuels améliorés** : Ajout d'un dégradé radial et d'un effet de brillance pour un rendu plus moderne.
4. **Animation de sélection** : La tuile s'agrandit légèrement lorsqu'elle est sélectionnée grâce à `withScale`.

Cette version est beaucoup plus adaptable aux différentes tailles d'écran et orientations, tout en améliorant l'aspect visuel du composant.

