Comme je n'ai pas vu le code exact de `EnhancedGrid` dans les fichiers que vous avez partagés, je vais vous proposer une solution qui devrait fonctionner avec la plupart des implémentations de grille, en supposant qu'elle utilise `EnhancedLetterTile` pour afficher les lettres.

Voici comment adapter `EnhancedGrid` pour qu'il fonctionne avec notre `EnhancedLetterTile` modifié :

```kotlin
@Composable
fun EnhancedGrid(
    letters: List<Char>,
    selectedIndices: List<Int>,
    onLetterClick: (Int) -> Unit,
    modifier: Modifier = Modifier
) {
    // Utiliser BoxWithConstraints pour obtenir l'espace disponible
    BoxWithConstraints(modifier = modifier) {
        val configuration = LocalConfiguration.current
        val isLandscape = configuration.orientation == Configuration.ORIENTATION_LANDSCAPE

        // Calculer la taille optimale de la grille en fonction de l'espace disponible
        val gridSize = if (isLandscape) {
            maxHeight.times(0.8f)
        } else {
            maxWidth.times(0.9f)
        }

        // Calculer le nombre de colonnes (généralement 7 pour un jeu de mots)
        val columns = 7
        val rows = (letters.size + columns - 1) / columns

        // Calculer la taille des tuiles en fonction de l'espace disponible
        val tileSize = (gridSize / columns.coerceAtLeast(1)).coerceAtMost(64.dp)

        // Espacement entre les tuiles
        val spacing = (tileSize.value * 0.1f).dp

        // Créer la grille
        Column(
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(spacing),
            modifier = Modifier.width(gridSize)
        ) {
            // Diviser les lettres en rangées
            for (rowIndex in 0 until rows) {
                Row(
                    horizontalArrangement = Arrangement.spacedBy(spacing),
                    modifier = Modifier.fillMaxWidth(),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    val startIndex = rowIndex * columns
                    val endIndex = minOf(startIndex + columns, letters.size)

                    // Centrer la dernière rangée si elle n'est pas complète
                    if (endIndex - startIndex < columns) {
                        Spacer(modifier = Modifier.weight(1f))
                    }

                    // Afficher les lettres de cette rangée
                    for (i in startIndex until endIndex) {
                        EnhancedLetterTile(
                            letter = letters[i],
                            index = i,
                            isSelected = selectedIndices.contains(i),
                            onClick = { onLetterClick(i) },
                            tileSize = tileSize
                        )
                    }

                    // Centrer la dernière rangée si elle n'est pas complète
                    if (endIndex - startIndex < columns) {
                        Spacer(modifier = Modifier.weight(1f))
                    }
                }
            }
        }
    }
}
```

