package com.example.pipwow.model

data class GameState(
    val currentLevel: Int = 1,
    val letters: String = "",
    val shuffledLetters: List<Char> = emptyList(),
    val selectedIndices: List<Int> = emptyList(),  // Main stockée comme List<Int>
    val foundWords: List<String> = emptyList(),
    val remainingWords: List<String> = emptyList(),
    val levelStartTime: Long = System.currentTimeMillis(),
    val isLevelCompleted: Boolean = false,
    val score: Int = 0,
    val hintUsedCount: Int = 0,
    val locationName: String = "",
    val hintUsed: Boolean = false,
    val multiplier: Int = 1,
    val lastFoundWord: String? = null,
    val backgroundColors: List<Long> = listOf(0xFF8B4513, 0xFFD2B48C) // Ajouter cette ligne
) {
    // Propriété calculée pour obtenir les lettres sélectionnées
    val selectedLetters: String
        get() = selectedIndices
            .map { shuffledLetters[it] } // Ne plus utiliser sorted()
            .joinToString("")

    // Méthodes utilitaires
    fun getCurrentWord(): String = selectedLetters

    fun isWordValid(word: String): Boolean = remainingWords.contains(word)

    fun calculateWordScore(word: String): Int = word.length * 10 * multiplier

    // Nouvelle méthode pour vérifier si une lettre est sélectionnée
    fun isLetterSelected(index: Int): Boolean = selectedIndices.contains(index)
}

