@Composable
fun WordCrossDisplay(
    foundWords: List<String>,
    crossSize: Int = 5,
    modifier: Modifier = Modifier
) {
    Box(
        modifier = modifier.size(120.dp),
        contentAlignment = Alignment.Center
    ) {
        Canvas(
            modifier = Modifier.fillMaxSize()
        ) {
            val centerX = size.width / 2
            val centerY = size.height / 2
            val squareSize = 20.dp.toPx()
            val spacing = 2.dp.toPx()

            // Dessiner la grille en croix
            for (i in 0 until crossSize) {
                for (j in 0 until crossSize) {
                    val shouldDraw = (i == crossSize / 2) || (j == crossSize / 2)

                    if (shouldDraw) {
                        val x = centerX - (crossSize * (squareSize + spacing)) / 2 + j * (squareSize + spacing)
                        val y = centerY - (crossSize * (squareSize + spacing)) / 2 + i * (squareSize + spacing)

                        // Couleur basée sur si un mot est trouvé à cette position
                        val wordIndex = if (i == crossSize / 2) j else i + crossSize
                        val isWordFound = wordIndex < foundWords.size

                        // Utiliser une variable locale pour la couleur au lieu de réassigner
                        val tileColor = if (isWordFound) Color(0xFF4CAF50) else Color.Gray.copy(alpha = 0.5f)

                        drawRoundRect(
                            color = tileColor,  // Utiliser la variable locale ici
                            topLeft = Offset(x, y),
                            size = Size(squareSize, squareSize),
                            cornerRadius = CornerRadius(4.dp.toPx())
                        )

                        // Dessiner la lettre si un mot est trouvé
                        if (isWordFound && wordIndex < foundWords.size) {
                            val word = foundWords[wordIndex]
                            if (word.isNotEmpty()) {
                                drawContext.canvas.nativeCanvas.apply {
                                    val textPaint = Paint().apply {
                                        color = android.graphics.Color.WHITE
                                        textSize = 12.sp.toPx()
                                        textAlign = Paint.Align.CENTER
                                        isFakeBoldText = true
                                    }

                                    drawText(
                                        word.first().toString(),
                                        x + squareSize / 2,
                                        y + squareSize / 2 + 4.dp.toPx(),
                                        textPaint
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

