package fr.cat.tcc.sj.breadcrumb;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpSession;
import org.aspectj.lang.JoinPoint;
import org.aspectj.lang.annotation.Aspect;
import org.aspectj.lang.annotation.Before;
import org.springframework.stereotype.Component;
import org.springframework.web.context.request.RequestContextHolder;
import org.springframework.web.context.request.ServletRequestAttributes;

import java.util.ArrayList;
import java.util.List;

@Aspect
@Component
public class BreadcrumbAspect {

    private static final String SESSION_ATTR = "breadcrumbs";

    @Before("@annotation(breadcrumbMapping)")
    public void before(JoinPoint jp, BreadcrumbMapping breadcrumbMapping) {
        ServletRequestAttributes attrs =
                (ServletRequestAttributes) RequestContextHolder.getRequestAttributes();
        if (attrs == null) return;

        HttpServletRequest request = attrs.getRequest();
        HttpSession session = request.getSession();

        @SuppressWarnings("unchecked")
        List<BreadcrumbItem> crumbs = (List<BreadcrumbItem>) session.getAttribute(SESSION_ATTR);
        if (crumbs == null) {
            crumbs = new ArrayList<>();
        }

        // First level must always be HOME
        Breadcrumb homeInfo = Breadcrumb.HOME;
        BreadcrumbItem homeItem = new BreadcrumbItem(homeInfo.getTitle(), "/");
        if (crumbs.isEmpty() || !crumbs.get(0).equals(homeItem)) {
            crumbs.clear();
            crumbs.add(homeItem);
        }

        // Current Breadcrumb Item
        Breadcrumb currentBreadCrumb = breadcrumbMapping.value();
        String path = request.getServletPath();

        // Build path with query params if present
        String qs = request.getQueryString();
        if (qs != null && !qs.isEmpty()) {
            path += "?" + qs;
        }

        BreadcrumbItem newBreadcrumbItem = new BreadcrumbItem(currentBreadCrumb.getTitle(), path);

        // 3) if HOME is clicked, reset all
        if (currentBreadCrumb == homeInfo) {
            crumbs.clear();
            crumbs.add(homeItem);
        } else if (currentBreadCrumb.getParent() != null) {
            Breadcrumb parent = currentBreadCrumb.getParent();
            // on cherche l’index du parent dans la List<BreadcrumbItem>
            int parentIndex = -1;
            for (int i = 0; i < crumbs.size(); i++) {
                if (crumbs.get(i).getTitle().equals(parent.getTitle())) {
                    parentIndex = i;
                    break;
                }
            }
            if (parentIndex >= 0) {
                // supprime tous les éléments après le parent
                crumbs.subList(parentIndex + 1, crumbs.size()).clear();
            }
            // ajoute le nouvel item
            crumbs.add(newBreadcrumbItem);

// 5) sinon on a un élément “isolé” :
//    - s’il existe déjà, on reset (home + lui),
        } else {
            // if element already exist, reset
            boolean alreadyThere = crumbs.contains(newBreadcrumbItem);
            if (alreadyThere) {
                crumbs.clear();
                crumbs.add(homeItem);
                crumbs.add(newBreadcrumbItem);
            } else {
                crumbs.add(newBreadcrumbItem);
            }
        }
        session.setAttribute(SESSION_ATTR, crumbs);
    }
}

