            // Restore data to destination Redis
            await RestoreRedisData(destinationRedisConnection, backupFilePath);

            Console.WriteLine("Process completed successfully!");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }

    static async Task BackupRedisData(string connectionString, string backupFilePath)
    {
        Console.WriteLine("Starting backup process...");

        using (var redis = ConnectionMultiplexer.Connect(connectionString))
        {
            IDatabase db = redis.GetDatabase();
            IServer server = redis.GetServer(connectionString);

            using (StreamWriter writer = new StreamWriter(backupFilePath))
            {
                // Iterate through all keys
                foreach (var key in server.Keys())
                {
                    string keyString = key.ToString();
                    RedisType type = db.KeyType(keyString);
                    string value = "";

                    // Handle different types of Redis values
                    switch (type)
                    {
                        case RedisType.String:
                            value = db.StringGet(keyString);
                            await writer.WriteLineAsync($"string|{keyString}|{value}");
                            break;

                        case RedisType.List:
                            var listValues = db.ListRange(keyString);
                            value = string.Join(",", listValues);
                            await writer.WriteLineAsync($"list|{keyString}|{value}");
                            break;

                        case RedisType.Set:
                            var setMembers = db.SetMembers(keyString);
                            value = string.Join(",", setMembers);
                            await writer.WriteLineAsync($"set|{keyString}|{value}");
                            break;

                        case RedisType.Hash:
                            var hashFields = db.HashGetAll(keyString);
                            var hashEntries = new List<string>();
                            foreach (var entry in hashFields)
                            {
                                hashEntries.Add($"{entry.Name}={entry.Value}");
                            }
                            value = string.Join(",", hashEntries);
                            await writer.WriteLineAsync($"hash|{keyString}|{value}");
                            break;

                        // Add more cases for other Redis types as needed
                    }
                }
            }
        }

        Console.WriteLine("Backup completed successfully!");
    }

    static async Task RestoreRedisData(string connectionString, string backupFilePath)
    {
        Console.WriteLine("Starting restore process...");

        using (var redis = ConnectionMultiplexer.Connect(connectionString))
        {
            IDatabase db = redis.GetDatabase();

            string[] lines = await File.ReadAllLinesAsync(backupFilePath);

            foreach (string line in lines)
            {
                string[] parts = line.Split('|');
                if (parts.Length != 3) continue;

                string type = parts[0];
                string key = parts[1];
                string value = parts[2];

                switch (type)
                {
                    case "string":
                        await db.StringSetAsync(key, value);
                        break;

                    case "list":
                        if (!string.IsNullOrEmpty(value))
                        {
                            string[] listValues = value.Split(',');
                            foreach (string listValue in listValues)
                            {
                                await db.ListRightPushAsync(key, listValue);
                            }
                        }
                        break;

                    case "set":
                        if (!string.IsNullOrEmpty(value))
                        {
                            string[] setValues = value.Split(',');
                            foreach (string setValue in setValues)
                            {
                                await db.SetAddAsync(key, setValue);
                            }
                        }
                        break;

                    case "hash":
