```python
import pygame
import random

# Constantes
HAUTEUR = 600
LARGEUR = 400
TAILLE_CASE = 20
COULEURS = {
    "I": (255, 255, 255),
    "J": (0, 0, 255),
    "L": (255, 165, 0),
    "O": (255, 255, 0),
    "S": (0, 255, 0),
    "T": (128, 0, 128),
    "Z": (255, 0, 0)
}

# Formes des pièces
FORMES = {
    "I": [[1, 1, 1, 1]],
    "J": [[1, 0, 0], [1, 1, 1]],
    "L": [[0, 0, 1], [1, 1, 1]],
    "O": [[1, 1], [1, 1]],
    "S": [[0, 1, 1], [1, 1, 0]],
    "T": [[0, 1, 0], [1, 1, 1]],
    "Z": [[1, 1, 0], [0, 1, 1]]
}

class Piece:
    def __init__(self, type_piece):
        self.type_piece = type_piece
        self.forme = FORMES[type_piece]
        self.x = LARGEUR // 2
        self.y = 0
        self.rotation = 0

    def rotate(self):
        self.rotation += 1
        if self.rotation == 4:
            self.rotation = 0

    def get_forme(self):
        if self.rotation == 0:
            return self.forme
        elif self.rotation == 1:
            return [list(reversed(col)) for col in zip(*self.forme)]
        elif self.rotation == 2:
            return [list(reversed(ligne)) for ligne in self.forme]
        elif self.rotation == 3:
            return [list(col) for col in zip(*self.forme)[::-1]]

class Tetris:
    def __init__(self):
        pygame.init()
        self.ecran = pygame.display.set_mode((LARGEUR, HAUTEUR))
        self.clock = pygame.time.Clock()
        self.piece_actuelle = Piece(random.choice(list(FORMES.keys())))
        self.grille = [[0 for _ in range(LARGEUR // TAILLE_CASE)] for _ in range(HAUTEUR // TAILLE_CASE)]

    def dessiner_piece(self, piece):
        forme = piece.get_forme()
        for y, ligne in enumerate(forme):
            for x, case in enumerate(ligne):
                if case == 1:
                    pygame.draw.rect(self.ecran, COULEURS[piece.type_piece], (piece.x + x * TAILLE_CASE, piece.y + y * TAILLE_CASE, TAILLE_CASE, TAILLE_CASE))

    def dessiner_grille(self):
        for y, ligne in enumerate(self.grille):
            for x, case in enumerate(ligne):
                if case == 1:
                    pygame.draw.rect(self.ecran, (128, 128, 128), (x * TAILLE_CASE, y * TAILLE_CASE, TAILLE_CASE, TAILLE_CASE))

    def update(self):
        self.piece_actuelle.y += TAILLE_CASE
        if self.piece_actuelle.y + len(self.piece_actuelle.get_forme()) * TAILLE_CASE > HAUTEUR:
            self.piece_actuelle.y = HAUTEUR - len(self.piece_actuelle.get_forme()) * TAILLE_CASE
            self.grille = self.maj_grille(self.piece_actuelle)
            self.piece_actuelle = Piece(random.choice(list(FORMES.keys())))

    def maj_grille(self, piece):
        forme = piece.get_forme()
        grille = self.grille[:]
        for y, ligne in enumerate(forme):
            for x, case in enumerate(ligne):
                if case == 1:
                    grille[(piece.y + y * TAILLE_CASE) // TAILLE_CASE][(piece.x + x * TAILLE_CASE) // TAILLE_CASE] = 1
        return grille

    def run(self):
        while True:
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    pygame.quit()
                    sys.exit()
                elif event.type == pygame.KEYDOWN:
                    if event.key == pygame.K_LEFT:
                        self.piece_actuelle.x -= TAILLE_CASE
                    elif event.key == pygame.K_RIGHT:
                        self.piece_actuelle.x += TAILLE_CASE
                    elif event.key == pygame.K_DOWN:
                        self.update()
                    elif event.key == pygame.K_UP:
                        self.piece_actuelle.rotate()

            self.ecran.fill((0, 0, 0))
            self.dessiner_grille()
            self.dessiner_piece(self.piece_actuelle)
            pygame.display.flip()
            self.clock.tick(60)

if __name__ == "__main__":
    tetris = Tetris()
    tetris.run()
```
Ce code utilise la bibliothèque Pygame pour créer une fenêtre et gérer les événements. Il définit une classe `Piece` pour représenter les pièces du jeu et une classe `Tetris` pour gérer le jeu. La méthode `run` de la classe `Tetris` est la boucle principale du jeu.

Notez que ce code est un exemple de base et qu'il faudra probablement le modifier pour améliorer le gameplay et ajouter des fonctionnalités supplémentaires.

