    private int insertionSkipLimit;

    @Value("${app.file.prefix.just.trace}")
    private String filenameJustTrace;

    @Value("${path.file.emission}")
    private String pathFileEmission;

    @Autowired
    public BatTraceJustJob(final JobBuilderFactory jobBuilderFactory, final StepBuilderFactory stepBuilderFactory, final LogContext logContext) {
        this.jobBuilderFactory = jobBuilderFactory;
        this.stepBuilderFactory = stepBuilderFactory;
        this.logContext = logContext;
    }

    @Bean
    public ItemReader<BatTraceJust> batTraceJustItemReader() {
        return new BatTraceJustReader(this.logContext);
    }

    @Bean
    public BatTraceJustProcessor batTraceJustItemProcessor() {
        return new BatTraceJustProcessor(this.logContext, this.statsData());
    }

    @Bean
    public BatTraceJustProcessorListener batTraceJustItemProcessorListener() {
        return new BatTraceJustProcessorListener(this.logContext);
    }

    @Bean
    @StepScope
    public BatTraceJustWriterListener batTraceJustItemWriterListener() {
        return new BatTraceJustWriterListener(this.logContext);
    }

    @Bean("ArchivageJustTrace")
    @StepScope
    public StepArchiveListener batVirementArchiveListener() {
        return new StepArchiveListener(FilenameGeneratorFacade.generateWithDate(this.filenameJustTrace));
    }

    @Bean
    @StepScope
    public BatTraceJustItemWriter batTraceJustItemWriter() {
        return new BatTraceJustItemWriter(this.pathFileEmission + this.filenameJustTrace);
    }

    @Bean
    public Step traitementTraceJustStep() {
        return this.stepBuilderFactory.get("TRAITEMENT_TRACE_JUST_INSERT")
            .<BatTraceJust, List<BatTraceJustDTO>>chunk(1)
            .reader(this.batTraceJustItemReader())
            .processor(this.batTraceJustItemProcessor())
            .writer(this.batTraceJustItemWriter())
            .listener(this.batVirementArchiveListener())
            .listener(this.batTraceJustItemProcessorListener())
            .listener(this.batTraceJustItemWriterListener())
            .faultTolerant()
            .skipLimit(this.insertionSkipLimit)
            .skip(SkipException.class)
            .taskExecutor(this.threadPoolTaskExecutor())
            .throttleLimit(this.nproc)
            .allowStartIfComplete(true)
            .build();
    }

    @Override
