            .incrementer(new RunIdIncrementer())
            .listener(new JobListener(this.logContext))
            .start(this.traitementTraceJustStep())
            .next(this.findFilePathTask())
            .next(this.buildFunctionnalLogger(BatTraceJustJob.functionnalLogger()))
            .build();
    }

    protected Step buildFunctionnalLogger(final Tasklet tasklet) {
        return this.stepBuilderFactory.get("BAT_JUST_LOG_STEP").tasklet(tasklet).build();
    }

    private static TraceJustFuncLogTasklet functionnalLogger() {
        return Beans.get(TraceJustFuncLogTasklet.class);
    }

    @Bean("TraceJustStatsData")
    public TraceJustStatsData statsData() {
        return new TraceJustStatsData();
    }

    private Step findFilePathTask() {
        return this.stepBuilderFactory.get("VIREMENT_FILE_PATH_STEP").tasklet(Beans.get(ArchiveArchCopyTasklet.class))
            .build();
