// EmployeeManagementActivity.java
public class EmployeeManagementActivity extends AppCompatActivity {
    private ActivityEmployeeManagementBinding binding;
    private AppDatabase database;
    private EmployeeAdapter adapter;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        binding = ActivityEmployeeManagementBinding.inflate(getLayoutInflater());
        setContentView(binding.getRoot());

        database = AppDatabase.getInstance(this);
        setupRecyclerView();
        setupAddButton();
    }

    private void setupRecyclerView() {
        adapter = new EmployeeAdapter(new ArrayList<>());
        binding.recyclerView.setAdapter(adapter);
        binding.recyclerView.setLayoutManager(new LinearLayoutManager(this));
        loadEmployees();
    }

    private void loadEmployees() {
        new Thread(() -> {
            List<User> employees = database.userDao().getUsersByRole("EMPLOYEE");
            runOnUiThread(() -> adapter.updateEmployees(employees));
        }).start();
    }

    private void setupAddButton() {
        binding.fabAddEmployee.setOnClickListener(v -> showAddEmployeeDialog());
    }

    private void showAddEmployeeDialog() {
        AddEmployeeDialogBinding dialogBinding = AddEmployeeDialogBinding.inflate(getLayoutInflater());
        AlertDialog dialog = new AlertDialog.Builder(this)
            .setTitle("Add Employee")
            .setView(dialogBinding.getRoot())
            .setPositiveButton("Add", (dialogInterface, i) -> {
                String name = dialogBinding.etName.getText().toString();
                String email = dialogBinding.etEmail.getText().toString();
                String password = dialogBinding.etPassword.getText().toString();

                if (!name.isEmpty() && !email.isEmpty() && !password.isEmpty()) {
                    addEmployee(new User(UUID.randomUUID().toString(), name, email, password, "EMPLOYEE"));
                }
            })
            .setNegativeButton("Cancel", null)
            .create();
        dialog.show();
    }

    private void addEmployee(User employee) {
        new Thread(() -> {
            database.userDao().insert(employee);
            runOnUiThread(this::loadEmployees);
        }).start();
    }
}
