class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContent {
            MaterialTheme {
                GameScreen()
            }
        }
    }
}

// 🧭 Direction enum
enum class Direction { HORIZONTAL, VERTICAL }

// 🧩 Mot positionné dans la grille
data class PositionedWord(
    val word: String,
    val row: Int,
    val col: Int,
    val direction: Direction
)

// 🎯 Niveau avec grille
data class CrosswordLevel(
    val words: List<PositionedWord>,
    val gridSize: Int = 10
)

// 🎮 ViewModel du jeu
class GameViewModel : ViewModel() {
    companion object {
        private const val MIN_WORD_LENGTH = 3
    }

    private fun calculateGridBounds(words: List<PositionedWord>): Pair<Int, Int> {
        var maxRow = 0
        var maxCol = 0

        for (word in words) {
            val endRow = if (word.direction == Direction.VERTICAL) word.row + word.word.length else word.row
            val endCol = if (word.direction == Direction.HORIZONTAL) word.col + word.word.length else word.col
            maxRow = maxOf(maxRow, endRow)
            maxCol = maxOf(maxCol, endCol)
        }

        return Pair(maxRow + 1, maxCol + 1) // +1 to include last index
    }
    private val levels = listOf(
        CrosswordLevel(
            words = listOf(
                PositionedWord("FRANCE", row = 2, col = 1, direction = Direction.HORIZONTAL),
                PositionedWord("PARIS", row = 0, col = 3, direction = Direction.VERTICAL),
                PositionedWord("LOUVRE", row = 4, col = 1, direction = Direction.HORIZONTAL)
            )
        ),
        CrosswordLevel(
            words = listOf(
                PositionedWord("BERLIN", row = 1, col = 2, direction = Direction.HORIZONTAL),
                PositionedWord("MUSEUM", row = 0, col = 4, direction = Direction.VERTICAL),
                PositionedWord("REICH", row = 5, col = 2, direction = Direction.HORIZONTAL)
            )
        )
    )

    private var currentLevelIndex = 0

    private val _grid = MutableStateFlow(Array(10) { CharArray(10) { ' ' } })
    val grid: StateFlow<Array<CharArray>> = _grid.asStateFlow()
    private val _currentWord = mutableStateOf("")
    val currentWord: State<String> = _currentWord
    private val _foundWords = MutableStateFlow<List<String>>(emptyList())
    val foundWords: StateFlow<List<String>> = _foundWords.asStateFlow()

    private val _selectedWord = MutableStateFlow("")
    val selectedWord: StateFlow<String> = _selectedWord.asStateFlow()

    private val _feedback = MutableStateFlow("")
    val feedback: StateFlow<String> = _feedback.asStateFlow()

    private val _letters = MutableStateFlow<List<Char>>(emptyList())
    val letters: StateFlow<List<Char>> = _letters.asStateFlow()

    init {
        startLevel()
    }
    fun removeLastSelectedLetter() {
        val current = _selectedWord.value
        if (current.isNotEmpty()) {
            _selectedWord.value = current.dropLast(1)
        }
    }




    fun removeLastLetter() {
        if (_currentWord.value.isNotEmpty()) {
            _currentWord.value = _currentWord.value.dropLast(1)
        }
    }
    private fun startLevel() {
        val level = levels[currentLevelIndex]
        _foundWords.value = emptyList()
        _selectedWord.value = ""
        _feedback.value = ""
        _letters.value = level.words.flatMap { it.word.toList() }.shuffled()
        updateGrid()
    }

    private fun updateGrid() {
        val level = levels[currentLevelIndex]
        val (rows, cols) = calculateGridBounds(level.words)
        val newGrid = Array(rows) { CharArray(cols) { ' ' } }

        for (word in level.words) {
            if (_foundWords.value.contains(word.word)) {
                for (i in word.word.indices) {
                    val r = if (word.direction == Direction.VERTICAL) word.row + i else word.row
                    val c = if (word.direction == Direction.HORIZONTAL) word.col + i else word.col
                    newGrid[r][c] = word.word[i]
                }
            }
        }

        _grid.value = newGrid
    }

    fun selectLetter(letter: Char) {
        val updated = _selectedWord.value + letter
        _selectedWord.value = updated

        if (updated.length >= MIN_WORD_LENGTH) {
            checkWord()
        }
    }



    private fun checkWord() {
        val levelWords = levels[currentLevelIndex].words.map { it.word }
        val word = _selectedWord.value

        if (levelWords.contains(word) && !_foundWords.value.contains(word)) {
            _foundWords.value = _foundWords.value + word
            _feedback.value = "Bravo !"
            _selectedWord.value = ""
            updateGrid()
            if (_foundWords.value.size == levelWords.size) {
                currentLevelIndex++
                if (currentLevelIndex < levels.size) {
                    startLevel()
                } else {
                    _feedback.value = "🎉 Jeu terminé !"
                }
            }
        } else if (word.length >= levelWords.maxOf { it.length }) {
            _feedback.value = "Mot incorrect"
            _selectedWord.value = ""
        } else {
            _feedback.value = ""
        }
    }
}

// 🖼️ UI principale
@Composable
fun GameScreen(viewModel: GameViewModel = viewModel()) {
    val grid by viewModel.grid.collectAsState()
    val letters by viewModel.letters.collectAsState()
    val feedback by viewModel.feedback.collectAsState()
    val selectedWord by viewModel.selectedWord.collectAsState()

    Column(modifier = Modifier.padding(16.dp)) {
        Text("Grille du niveau", fontWeight = FontWeight.Bold, fontSize = 20.sp)

        Column {
            grid.forEach { row ->
                Row {
                    row.forEach { cell ->
                        Box(
                            modifier = Modifier
                                .size(32.dp)
                                .border(1.dp, Color.Gray)
                                .background(if (cell != ' ') Color.LightGray else Color.White),
                            contentAlignment = Alignment.Center
                        ) {
                            Text(cell.toString(), fontSize = 18.sp)
                        }
                    }
                }
            }
        }

        Spacer(modifier = Modifier.height(16.dp))
        Text("Mot sélectionné : $selectedWord", fontSize = 18.sp)

        LazyVerticalGrid(columns = GridCells.Fixed(6), modifier = Modifier.height(200.dp)) {
            items(letters.size) { index ->
                val letter = letters[index]
                Box(
                    modifier = Modifier
                        .padding(4.dp)
                        .size(40.dp)
                        .clickable { viewModel.selectLetter(letter) }
                        .background(Color(0xFFE0E0E0)),
                    contentAlignment = Alignment.Center
                ) {
                    Text(letter.toString(), fontSize = 20.sp)
                }
            }
        }

        Spacer(modifier = Modifier.height(8.dp))
        // 🆕 Bouton pour effacer la dernière lettre
        Button(
            onClick = { viewModel.removeLastSelectedLetter() },
            modifier = Modifier.padding(vertical = 8.dp)
        ) {
            Text("Effacer la dernière lettre")
        }

        Text(feedback, color = if (feedback == "Bravo !") Color.Green else Color.Red, fontSize = 16.sp)
    }
