    private fun calculateGridBounds(words: List<PositionedWord>): Pair<Int, Int> {
        var maxRow = 0
        var maxCol = 0

        for (word in words) {
            val endRow = if (word.direction == Direction.VERTICAL) word.row + word.word.length else word.row
            val endCol = if (word.direction == Direction.HORIZONTAL) word.col + word.word.length else word.col
            maxRow = maxOf(maxRow, endRow)
