```kotlin
import android.app.Application
import android.content.Context
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.viewModelScope
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import kotlinx.serialization.Serializable
import kotlinx.serialization.decodeFromString
import kotlinx.serialization.json.Json

class GameViewModel(application: Application) : AndroidViewModel(application) {

    // Configuration JSON
    private val json = Json { ignoreUnknownKeys = true }

    // Constantes
    companion object {
        private const val MIN_WORD_LENGTH = 3
    }

    // Données du jeu
    private val _grid = MutableStateFlow(Array(10) { CharArray(10) { ' ' } })
    val grid: StateFlow<Array<CharArray>> = _grid.asStateFlow()

    private val _letters = MutableStateFlow<List<Char>>(emptyList())
    val letters: StateFlow<List<Char>> = _letters.asStateFlow()

    private val _selectedWord = MutableStateFlow("")
    val selectedWord: StateFlow<String> = _selectedWord.asStateFlow()

    private val _foundWords = MutableStateFlow<List<String>>(emptyList())
    val foundWords: StateFlow<List<String>> = _foundWords.asStateFlow()

    private val _feedback = MutableStateFlow("")
    val feedback: StateFlow<String> = _feedback.asStateFlow()

    private var currentLevelIndex = 0
    private lateinit var levels: List<CrosswordLevel>

    init {
        loadGameData()
    }

    private fun loadGameData() {
        viewModelScope.launch {
            levels = loadLevelsFromJson(getApplication())
            startLevel()
        }
    }

    private fun loadLevelsFromJson(context: Context): List<CrosswordLevel> {
        val jsonString = context.resources.openRawResource(R.raw.crosswords)
            .bufferedReader()
            .use { it.readText() }

        val crosswordJson = json.decodeFromString<CrosswordJson>(jsonString)
        return crosswordJson.levels.map { levelJson ->
            CrosswordLevel(
                words = levelJson.words.map { it.toPositionedWord() },
                gridSize = 10
            )
        }
    }

    private fun startLevel() {
        if (currentLevelIndex < levels.size) {
            val level = levels[currentLevelIndex]
            _foundWords.value = emptyList()
            _selectedWord.value = ""
            _feedback.value = ""
            _letters.value = level.words.flatMap { it.word.toList() }.shuffled()
            updateGrid()
        }
    }

    private fun updateGrid() {
        val level = levels[currentLevelIndex]
        val (rows, cols) = calculateGridBounds(level.words)
        val newGrid = Array(rows) { CharArray(cols) { ' ' } }

        level.words.forEach { word ->
            if (_foundWords.value.contains(word.word)) {
                for (i in word.word.indices) {
                    val r = if (word.direction == Direction.VERTICAL) word.row + i else word.row
                    val c = if (word.direction == Direction.HORIZONTAL) word.col + i else word.col
                    newGrid[r][c] = word.word[i]
                }
            }
        }

        _grid.value = newGrid
    }

    private fun calculateGridBounds(words: List<PositionedWord>): Pair<Int, Int> {
        var maxRow = 0
        var maxCol = 0

        words.forEach { word ->
            val endRow = if (word.direction == Direction.VERTICAL) word.row + word.word.length else word.row
            val endCol = if (word.direction == Direction.HORIZONTAL) word.col + word.word.length else word.col
            maxRow = maxOf(maxRow, endRow)
            maxCol = maxOf(maxCol, endCol)
        }

        return Pair(maxRow + 1, maxCol + 1)
    }

    fun selectLetter(letter: Char) {
        _selectedWord.value += letter
        if (_selectedWord.value.length >= MIN_WORD_LENGTH) {
            checkWord()
        }
    }

    fun removeLastSelectedLetter() {
        if (_selectedWord.value.isNotEmpty()) {
            _selectedWord.value = _selectedWord.value.dropLast(1)
        }
    }

    private fun checkWord() {
        val levelWords = levels[currentLevelIndex].words.map { it.word }
        val word = _selectedWord.value

        when {
            levelWords.contains(word) && !_foundWords.value.contains(word) -> {
                _foundWords.value += word
                _feedback.value = "Bravo !"
                _selectedWord.value = ""
                updateGrid()

                if (_foundWords.value.size == levelWords.size) {
                    currentLevelIndex++
                    if (currentLevelIndex < levels.size) {
                        startLevel()
                    } else {
                        _feedback.value = "🎉 Jeu terminé !"
                    }
                }
            }
            word.length >= levelWords.maxOf { it.length } -> {
                _feedback.value = "Mot incorrect"
                _selectedWord.value = ""
            }
            else -> {
                _feedback.value = ""
            }
        }
    }
}

// Classes de sérialisation
@Serializable
private data class CrosswordJson(val levels: List<CrosswordLevelJson>)

@Serializable
private data class CrosswordLevelJson(val words: List<PositionedWordJson>)

@Serializable
private data class PositionedWordJson(
    val word: String,
    val row: Int,
    val col: Int,
    val direction: String
) {
    fun toPositionedWord() = PositionedWord(
        word = word,
        row = row,
        col = col,
        direction = enumValueOf(direction)
    )
}
```

