```kotlin
private fun loadLevelsFromJson(context: Context): List<CrosswordLevel> {
    return try {
        // 1. Vérification de l'existence du fichier
        val resId = context.resources.getIdentifier(
            "crosswords",
            "raw", 
            context.packageName
        ).takeIf { it != 0 } ?: throw IllegalArgumentException("Fichier crosswords.json introuvable dans res/raw")

        // 2. Lecture du fichier avec vérification de contenu
        val jsonString = context.resources.openRawResource(resId)
            .bufferedReader()
            .use { reader ->
                reader.readText().takeIf { it.isNotBlank() }
                    ?: throw IllegalStateException("Fichier JSON vide ou invalide")
            }

        // 3. Log du contenu pour débogage (à désactiver en production)
        Log.d("JSON_LOADER", "Contenu JSON lu:\n$jsonString")

        // 4. Désérialisation avec gestion d'erreur
        val parsedData = json.decodeFromString<CrosswordJson>(jsonString)

        // 5. Validation des données
        if (parsedData.levels.isEmpty()) {
            throw IllegalStateException("Aucun niveau trouvé dans le JSON")
        }

        // 6. Conversion en modèle de domaine
        parsedData.levels.map { levelJson ->
            CrosswordLevel(
                words = levelJson.words.map { jsonWord ->
                    PositionedWord(
                        word = jsonWord.word.uppercase(), // Uniformisation
                        row = jsonWord.row.coerceAtLeast(0),
                        col = jsonWord.col.coerceAtLeast(0),
                        direction = try {
                            enumValueOf<Direction>(jsonWord.direction.uppercase())
                        } catch (e: IllegalArgumentException) {
                            Log.w("JSON_LOADER", "Direction invalide '${jsonWord.direction}', utilisation HORIZONTAL par défaut")
                            Direction.HORIZONTAL
                        }
                    )
                },
                gridSize = 10 // Taille par défaut
            )
        }
    } catch (e: Exception) {
        Log.e("JSON_LOADER", "Erreur de chargement du JSON", e)

        // 7. Fallback avec niveau par défaut
        listOf(
            CrosswordLevel(
                words = listOf(
                    PositionedWord("ERREUR", 0, 0, Direction.HORIZONTAL),
                    PositionedWord("CHARGEMENT", 1, 0, Direction.VERTICAL)
                ),
                gridSize = 10
            )
        )
    }
}
```

