import org.springframework.web.context.request.RequestContextHolder;
import org.springframework.web.context.request.ServletRequestAttributes;

import java.util.ArrayList;
import java.util.List;

@Aspect
@Component
public class BreadcrumbAspect {

    private static final String SESSION_ATTR = "breadcrumbs";

    @Before("@annotation(breadcrumb)")
    public void before(JoinPoint jp, Breadcrumb breadcrumb) {
        ServletRequestAttributes attrs =
                (ServletRequestAttributes) RequestContextHolder.getRequestAttributes();
        if (attrs == null) return;

        HttpServletRequest request = attrs.getRequest();
        HttpSession session = request.getSession();

        @SuppressWarnings("unchecked")
        List<BreadcrumbItem> crumbs = (List<BreadcrumbItem>) session.getAttribute(SESSION_ATTR);
        if (crumbs == null) {
            crumbs = new ArrayList<>();
        }

        // First level must always be HOME
        BreadcrumbInfo homeInfo = BreadcrumbInfo.HOME;
        BreadcrumbItem homeItem = new BreadcrumbItem(homeInfo.getTitle(), homeInfo.getPath());
        if (crumbs.isEmpty() || !crumbs.get(0).equals(homeItem)) {
            crumbs.clear();
            crumbs.add(homeItem);
        }

        // Current Breadcrumb Item
        BreadcrumbInfo info = breadcrumb.value();
        String path = request.getContextPath() + "/" + info.getPath();
        if (breadcrumb.includeQueryParams()) {
            String qs = request.getQueryString();
            if (qs != null && !qs.isEmpty()) {
                path += "?" + qs;
            }
        }
        BreadcrumbItem current = new BreadcrumbItem(info.getTitle(), path);

        // 3) Si on clique HOME, on reset tout sur HOME
        if (info == homeInfo) {
            crumbs.clear();
            crumbs.add(homeItem);
        } else {
            // 4) Si on a déjà un élément de même type dans le fil => on réinitialise
            boolean alreadyThere = crumbs.contains(current);
            if (alreadyThere) {
                crumbs.clear();
                crumbs.add(homeItem);
                crumbs.add(current);
            } else {
                crumbs.add(current);
            }
        }

        session.setAttribute(SESSION_ATTR, crumbs);
    }
}

