// submit.service.ts  
@Injectable({providedIn: 'root'})  
export class SubmitService {  
  private _subj = new Subject<void>();  
  submit$ = this._subj.asObservable();  
  requestSubmit() { this._subj.next(); }  
}

// link.component.ts  
export class LinkComponent {  
  constructor(private srv: SubmitService) {}  
  onClick(e:MouseEvent) {  
    e.preventDefault();  
    this.srv.requestSubmit();  
  }  
}

// link.component.html  
<a href="#" (click)="onClick($event)">Submit autre form</a>

// form.component.ts  
export class FormComponent implements OnInit, OnDestroy {  
  private sub: Subscription;  
  constructor(private srv: SubmitService) {}  
  ngOnInit() {  
    this.sub = this.srv.submit$.subscribe(() => this.onSubmit());  
  }  
  onSubmit() {  
    // traitement du formulaire  
  }  
  ngOnDestroy() {  
    this.sub.unsubscribe();  
  }  
}

---

Ces deux patterns sont standards :  
- Parent médiateur pour des components reliés  
- Service + Subject/Observable pour un couplage lâche, composants totalement indépendants.

Puisque vos deux composants (le lien et le formulaire) ont un parent commun, le plus simple est :

1) Dans votre composant lien, émettre un événement quand on clique  
