export class LinkComponent {  
  @Output() clicked = new EventEmitter<void>();  
  onClick(e: MouseEvent) {  
    e.preventDefault();  
    this.clicked.emit();  
  }  
}

// link.component.html  
<a href="#" (click)="onClick($event)">Envoyer le formulaire</a>

