@Aspect
@Component
@SessionScope
public class BreadcrumbAspect {

    // Constante pour la clé de session (accessible dans Thymeleaf via ${session.breadcrumbs})
    private static final String BREADCRUMBS_SESSION_KEY = "breadcrumbs";

    // Liste des éléments du breadcrumb
    private List<BreadcrumbItem> breadcrumbs = new ArrayList<>();

    @Before("@annotation(breadcrumbMapping)")
    public void before(JoinPoint jp, BreadcrumbMapping breadcrumbMapping) {
        ServletRequestAttributes attrs = 
                (ServletRequestAttributes) RequestContextHolder.getRequestAttributes();
        if (attrs == null) return;

        HttpServletRequest request = attrs.getRequest();
        HttpSession session = request.getSession();

        // Premier niveau toujours HOME
        Breadcrumb homeInfo = Breadcrumb.HOME;
        BreadcrumbItem homeItem = new BreadcrumbItem(homeInfo.getTitle(), "/");

        // Correction du nom de variable (breadcrumbItems → breadcrumbs)
        if (breadcrumbs.isEmpty() || !breadcrumbs.get(0).equals(homeItem)) {
            breadcrumbs.clear();
            breadcrumbs.add(homeItem);
        }

        // Élément actuel
        Breadcrumb info = breadcrumbMapping.value();
        String path = request.getServletPath();

        // Ajouter les paramètres de requête
        String qs = request.getQueryString();
        if (qs != null && !qs.isEmpty()) {
            path += "?" + qs;
        }

        BreadcrumbItem current = new BreadcrumbItem(info.getTitle(), path);

        // Logique de gestion du breadcrumb
        if (info == homeInfo) {
            breadcrumbs.clear();
            breadcrumbs.add(homeItem);
        } else {
            boolean alreadyThere = breadcrumbs.contains(current);
            if (alreadyThere) {
                breadcrumbs.clear();
                breadcrumbs.add(homeItem);
                breadcrumbs.add(current);
            } else {
                breadcrumbs.add(current);
            }
        }

        // Sauvegarder dans la session avec la clé en constante
        session.setAttribute(BREADCRUMBS_SESSION_KEY, breadcrumbs);
    }
}
